# two-byte utf-8 sequences misread as latin-1 always produce a specific pair pattern:
# first byte is always one of C2-C3 (U+00C2..U+00C3, i.e. Â or Ã) followed by a
# continuation character in U+0080..U+00BF.  three-byte sequences start with E0-EF.
# we only attempt re-encoding when these tell-tale surrogate pairs are present.
_MOJIBAKE_RE = re.compile(
    r'(?:'
    r'[\xc2\xc3][\x80-\xbf]'          # 2-byte utf-8 pair: Â/Ã + continuation
    r'|[\xc4-\xc9\xcb-\xcf][\x80-\xbf]'  # other 2-byte leaders common in latin scripts
    r'|[\xe0-\xef][\x80-\xbf]{2}'     # 3-byte utf-8 triple
    r')'
)

def _fix_enc(s):
    """fix utf-8 bytes misread as latin-1 (mojibake); preserve already-correct utf-8"""
    if not s: return s
    try:
        s.encode('ascii')
        return s  # pure ascii - nothing to fix
    except UnicodeEncodeError:
        pass
    # only attempt re-encoding when the string contains recognisable mojibake
    # surrogate pairs (latin-1 code points that are utf-8 lead/continuation bytes).
    # this avoids mangling legitimate accented text like "café" or "Ångström".
    if not _MOJIBAKE_RE.search(s):
        return s
    try:
        return s.encode('latin-1').decode('utf-8')
    except (UnicodeEncodeError, UnicodeDecodeError):
        return s

def _subrun(args, **kw):
    """subprocess.run without console window on windows"""
    if sys.platform == 'win32':
        kw.setdefault('creationflags', subprocess.CREATE_NO_WINDOW)
    return subprocess.run(args, **kw)

# ── motionui paths ─────────────────────────────────────────────────────────────
_MU_REQUIRED = {"motionui.js", "components.css", "theme.css"}

def motionui_dir():
    # 1. sibling dir (dev / portable)
    candidates = [Path(__file__).parent / "motionui"]
    # 2. platform preferred install location (index 1 = where installer puts it)
    if sys.platform == 'win32':
        base = Path(os.environ.get('LOCALAPPDATA', Path.home() / "AppData" / "Local"))
        candidates.append(base / "Programs" / "motionui")
        candidates.append(base / "motionui")          # legacy fallback
    else:
        candidates.append(Path.home() / ".local" / "lib" / "motionui")
        candidates.append(Path.home() / ".local" / "share" / "motionui")
    for p in candidates:
        if all((p / f).exists() for f in _MU_REQUIRED):
            return str(p), False
    # return the preferred install path so the installer/popup knows where to put files
    install_target = candidates[1] if len(candidates) > 1 else candidates[0]
    return str(install_target), True

MOTIONUI_DIR, MU_MISSING = motionui_dir()

