_DEFS.update({"dbx_push_mode": "missing_on_peer", "dbx_quota_cap_pct": 80, "backup_keep_daily": 7, "backup_max_mb": 500, "glass_alpha": 1.0, "glass_blur": 1.0})

def load_cfg():
    _HOME.mkdir(parents=True, exist_ok=True)
    if _SCFG.exists():
        try:
            return {**_DEFS, **json.loads(_SCFG.read_text(encoding='utf-8'))}
        except Exception as e:
            # never silently fall through to factory defaults - that wipes every
            # saved setting in one shot. preserve the bad file for forensics and
            # recovery, and surface the failure loudly instead of swallowing it.
            try:
                _bak = _SCFG.with_suffix(_SCFG.suffix + f'.corrupt.{int(time.time())}')
                shutil.copy2(_SCFG, _bak)
                _log_server.error(f'[cfg] settings.json failed to parse ({e}); backed up to {_bak}, using defaults for this run only (NOT saved until next change)')
            except Exception as _be:
                _log_server.error(f'[cfg] settings.json failed to parse ({e}); backup also failed: {_be}')
    return dict(_DEFS)

def save_cfg(c):
    """Atomic write: temp file + fsync + os.replace, so a crash/kill/power-loss
    mid-write can never leave settings.json truncated or corrupt (which previously
    caused load_cfg() to silently reset every setting to factory defaults)."""
    _HOME.mkdir(parents=True, exist_ok=True)
    data = json.dumps(c, indent=2)
    tmp = _SCFG.with_suffix(_SCFG.suffix + f'.tmp.{os.getpid()}')
    try:
        with open(tmp, 'w', encoding='utf-8') as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, _SCFG)
    finally:
        try:
            if tmp.exists(): tmp.unlink()
        except Exception:
            pass

CFG = load_cfg()
_log_server.info(f'[cfg] path={_SCFG} token={bool(CFG.get("dropbox_refresh_token"))}')

