@app.route('/api/playlists/<pid>/songs', methods=['POST'])
def api_pl_add(pid):
    sid = (request.json or {}).get('song_id')
    if not sid: return jsonify({'error':'song_id required'}), 400
    with db() as c:
        if c.execute("SELECT 1 FROM playlist_songs WHERE playlist_id=? AND song_id=?", (pid,sid)).fetchone():
            return jsonify({'ok':True,'already':True})
        pos = c.execute("SELECT COALESCE(MAX(position),0)+1 FROM playlist_songs WHERE playlist_id=?", (pid,)).fetchone()[0]
        c.execute("INSERT INTO playlist_songs VALUES (?,?,?)", (pid,sid,pos))
        c.execute("UPDATE playlists SET modified_at=? WHERE id=?", (int(time.time()), pid))
        pl_row   = c.execute("SELECT sync_id FROM playlists WHERE id=?", (pid,)).fetchone()
        song_row = c.execute("SELECT sync_id FROM songs WHERE id=?", (sid,)).fetchone()
        if pl_row and pl_row[0] and song_row and song_row[0]:
            _record_sync_action('pl_add', pl_row[0], target2=song_row[0], conn=c)
    return jsonify({'ok':True})

