@app.route('/api/artists/<aid>/genius-discography')
def api_artist_genius_discography(aid):
    import urllib.parse
    tok = CFG.get('genius_token', '')
    if not tok:
        return jsonify({'error': 'no genius token'}), 400
    with db() as c:
        row = c.execute("SELECT * FROM artists WHERE id=?", (aid,)).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    artist = dict(row)
    genius_artist_id = artist.get('genius_artist_id')

    # if we don't have a genius artist id yet, try to get it from a song we already have
    if not genius_artist_id:
        name = artist['name']
        # first: check if any of this artist's songs already have a genius_id
        with db() as c:
            song_with_genius = c.execute("""
                SELECT s.genius_id FROM songs s
                JOIN song_artists sa ON sa.song_id = s.id
                WHERE sa.artist_id = ? AND s.genius_id IS NOT NULL
                LIMIT 1
            """, (aid,)).fetchone()
        if song_with_genius:
            song_data = _genius_get(f'/songs/{song_with_genius[0]}', tok).get('song', {})
            pa = (song_data.get('primary_artist') or {})
            if pa.get('id') and _fuzzy(pa.get('name', ''), name) >= 0.60:
                genius_artist_id = str(pa['id'])
                with db() as c:
                    c.execute("UPDATE artists SET genius_artist_id=? WHERE id=?", (genius_artist_id, aid))
        # fallback: search
        if not genius_artist_id:
            hits = _genius_get('/search?q=' + urllib.parse.quote(name), tok).get('hits', [])
            best_id = None
            best_score = 0.0
            for h in hits:
                if h.get('type') != 'song': continue
                pa = (h.get('result', {}).get('primary_artist') or {})
                sc = _fuzzy(pa.get('name', ''), name)
                if sc > best_score:
                    best_score = sc
                    best_id = pa.get('id')
            if not best_id or best_score < 0.60:
                return jsonify({'albums': [], 'songs': [], 'error': 'artist not found on genius'})
            genius_artist_id = str(best_id)
            with db() as c:
                c.execute("UPDATE artists SET genius_artist_id=? WHERE id=?", (genius_artist_id, aid))

    # fetch songs (paginated, sort by popularity, cap at 100)
    # only keep songs where this artist is the primary artist
    songs = []
    page = 1
    while page <= 5:
        resp = _genius_get(
            f'/artists/{genius_artist_id}/songs?per_page=20&page={page}&sort=popularity', tok
        )
        batch = resp.get('songs', [])
        if not batch:
            break
        for s in batch:
            primary = s.get('primary_artist') or {}
            if str(primary.get('id', '')) != str(genius_artist_id):
                continue
            songs.append({
                'genius_song_id': str(s.get('id', '')),
                'title': s.get('title', ''),
                'cover_url': s.get('song_art_image_thumbnail_url') or s.get('header_image_thumbnail_url', ''),
                'url': s.get('url', ''),
                'artist': primary.get('name', ''),
            })
        next_page = resp.get('next_page')
        if not next_page:
            break
        page = next_page
        _genius_rate_wait()

    # match against local data
    with db() as c:
        local_songs = c.execute("SELECT id, genius_id FROM songs WHERE genius_id IS NOT NULL").fetchall()
    genius_song_to_local = {r[1]: r[0] for r in local_songs if r[1]}

    for s in songs:
        s['local_song_id'] = genius_song_to_local.get(s['genius_song_id'])

    return jsonify({'albums': [], 'songs': songs})

@app.route('/api/artists/<aid>/ytm-profile')
def api_artist_ytm_profile(aid):
    """Fetch rich artist data from YTMusic by stored ytm_channel_id. Cached 6h in memory."""
    import time as _time
    now = _time.time()
    with _ytm_profile_cache_lock:
        if aid in _ytm_profile_cache and now - _ytm_profile_cache[aid][0] < 21600:
            return jsonify(_ytm_profile_cache[aid][1])
    with db() as c:
        row = c.execute("SELECT ytm_channel_id, name FROM artists WHERE id=?", (aid,)).fetchone()
    if not row: return jsonify({'error': 'not found'}), 404
    channel_id = row[0]
    if not channel_id:
        return jsonify({'error': 'no ytm_channel_id'}), 404
    try:
        yt = _import_ytmusic()
        data = yt.get_artist(channel_id)
    except Exception as e:
        return jsonify({'error': str(e)[:120]}), 500
    def _norm_section(key):
        sec = data.get(key) or {}
        out = []
        for r in (sec.get('results') or []):
            alb = r.get('album')
            out.append({
                'title':       r.get('title') or r.get('name') or '',
                'videoId':     r.get('videoId') or '',
                'browseId':    r.get('browseId') or '',
                'playlistId':  r.get('playlistId') or '',
                'album':       alb.get('name', '') if isinstance(alb, dict) else (alb or ''),
                'year':        r.get('year') or '',
                'views':       r.get('views') or '',
                'type':        r.get('type') or '',
                'subscribers': r.get('subscribers') or '',
                'thumbnail':   _ytm_thumbnail(r.get('thumbnails') or []),
            })
        return out
    desc_plain = ''
    runs = data.get('descriptionRuns') or []
    if runs:
        desc_plain = ''.join(r.get('text', '') for r in runs)
    elif data.get('description'):
        desc_plain = data['description']
    result = {
        'name':             data.get('name') or row[1],
        'channelId':        channel_id,
        'thumbnail':        _ytm_thumbnail(data.get('thumbnails') or []),
        'subscribers':      data.get('subscribers') or '',
        'views':            data.get('views') or '',
        'monthlyListeners': data.get('monthlyListeners') or '',
        'description':      desc_plain,
        'songs':            _norm_section('songs'),
        'albums':           _norm_section('albums'),
        'singles':          _norm_section('singles'),
        'videos':           _norm_section('videos'),
        'related':          _norm_section('related'),
    }
    with _ytm_profile_cache_lock:
        _ytm_profile_cache[aid] = (_time.time(), result)
    return jsonify(result)

@app.route('/api/artists/<aid>/fetch-image', methods=['POST'])
def api_artist_fetch_image(aid):
    import urllib.request, urllib.parse
    tok = CFG.get('genius_token', '')
    with db() as c:
        row = c.execute("SELECT * FROM artists WHERE id=?", (aid,)).fetchone()
    if not row: return jsonify({'error': 'not found'}), 404
    artist = dict(row)
    genius_artist_id = artist.get('genius_artist_id')
    if not genius_artist_id:
        return jsonify({'error': 'no genius artist id'}), 400
    resp = _genius_get(f'/artists/{genius_artist_id}', tok)
    a = resp.get('artist', {})
    img_url = a.get('image_url') or a.get('header_image_url')
    if not img_url:
        return jsonify({'error': 'no image found'})
    try:
        with urllib.request.urlopen(img_url, timeout=12) as r:
            data = r.read()
        p = cdir() / f'artist_{aid}.jpg'
        p.write_bytes(data)
        with db() as c:
            c.execute("UPDATE artists SET image_path=? WHERE id=?", (str(p), aid))
        return jsonify({'ok': True, 'image_path': str(p)})
    except Exception as e:
        return jsonify({'error': str(e)[:100]}), 500

@app.route('/api/artists/by-name')
def api_artist_by_name():
    name = request.args.get('name', '').strip()
    if not name: return jsonify({'error': 'name required'}), 400
    with db() as c:
        # exact match first
        row = c.execute("SELECT * FROM artists WHERE _ulower(name)=?", (name.lower(),)).fetchone()
        if not row:
            # alias match
            rows = c.execute("SELECT * FROM artists WHERE aliases != '[]'").fetchall()
            import json as _json
            for r in rows:
                aliases = _json.loads(r['aliases'] or '[]')
                if any(a.lower() == name.lower() for a in aliases):
                    row = r
                    break
        if not row:
            # fuzzy fallback
            all_rows = c.execute("SELECT * FROM artists").fetchall()
            best, best_score = None, 0.0
            for r in all_rows:
                sc = _fuzzy(r['name'], name)
                if sc > best_score:
                    best_score = sc
                    best = r
            if best and best_score > 0.82:
                row = best
    if not row: return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

