@app.route('/api/url-info', methods=['GET'])
def api_url_info():
    url = request.args.get('url', '').strip()
    if not url:
        return jsonify({'error': 'url required'}), 400
    if not re.match(r'https?://', url):
        return jsonify({'error': 'invalid url'}), 400
    try:
        r = _subrun(
            ['yt-dlp', '--dump-json', '--no-playlist', '--no-warnings', '--', url],
            capture_output=True, text=True, timeout=18)
        if r.returncode == 0 and r.stdout.strip():
            d = json.loads(r.stdout.strip())
            return jsonify({
                'title':     d.get('title', ''),
                'uploader':  d.get('uploader') or d.get('creator') or d.get('channel') or '',
                'thumbnail': d.get('thumbnail', ''),
                'duration':  d.get('duration'),
                'webpage_url': d.get('webpage_url') or url,
            })
    except Exception as _e:
        _log_library.warning('url-info err: %s', _e)
    return jsonify({'error': 'could not resolve url'}), 200

@app.route('/api/download', methods=['POST'])
def api_dl():
    data = request.json or {}
    q = data.get('query', '').strip()
    video_id = data.get('video_id', '').strip()
    genius_track_id = data.get('genius_track_id')
    is_video = bool(data.get('is_video', False))
    ytm_album = data.get('ytm_album') or None
    ytm_track_num = data.get('ytm_track_num') or 0
    ytm_track_title = data.get('ytm_track_title') or ''
    is_batch = bool(data.get('is_batch', False))
    batch_id = data.get('batch_id') or None
    spotify_url = _canon_spotify_url(data.get('spotify_url') or '')
    if not q and not video_id:
        return jsonify({'error': 'query or video_id required'}), 400
    did = str(uuid.uuid4())
    with _cfg_lock:
        fmt = CFG.get('format', 'mp3')
        quality = CFG.get('quality', '0')
    with _dl_lock:
        _dls[did] = {'status': 'pending', 'progress': 0, 'error': None, 'song_id': None, 'query': q or video_id}
    threading.Thread(target=_run_dl, args=(did, q, fmt, quality, genius_track_id, video_id),
                     kwargs={'is_video': is_video, 'ytm_album': ytm_album, 'ytm_track_num': int(ytm_track_num or 0), 'ytm_track_title': ytm_track_title, 'is_batch': is_batch, 'batch_id': batch_id, 'spotify_url': spotify_url},
                     daemon=True).start()
    return jsonify({'download_id': did})

@app.route('/api/download/batch', methods=['POST'])
def api_dl_batch():
    queries = (request.json or {}).get('queries', [])
    if not queries: return jsonify({'error':'queries required'}), 400
    ids = []
    with _cfg_lock:
        fmt = CFG.get('format','mp3')
        quality = CFG.get('quality','0')
    for q in queries:
        did = str(uuid.uuid4())
        with _dl_lock: _dls[did] = {'status':'pending','progress':0,'error':None,'song_id':None,'query':q}
        threading.Thread(target=_run_dl, args=(did,q,fmt,quality), kwargs={'is_batch':True}, daemon=True).start()
        ids.append(did)
    return jsonify({'download_ids': ids})

@app.route('/api/download/<did>')
def api_dl_status(did):
    _prune_dls()
    with _dl_lock: d = _dls.get(did)
    if not d: return jsonify({'error':'not found'}), 404
    return jsonify(d)

@app.route('/api/import', methods=['POST'])
def api_import():
    files = request.files.getlist('files')
    if not files or all(f.filename == '' for f in files):
        if 'file' in request.files and request.files['file'].filename:
            files = [request.files['file']]
        else:
            return jsonify({'error':'no file'}), 400
    results = []
    for f in files:
        if f.filename == '': continue
        ext = Path(f.filename).suffix.lower()
        if ext not in AUDIO_EXTS: continue
        sid = str(uuid.uuid4()); sync_id = str(uuid.uuid4()); mkdirs()
        dest = str(mdir()/f"{sid}{ext}")
        f.save(dest)
        meta = get_meta(dest)
        title = meta.get('title') or Path(f.filename).stem[:100]
        title = clean_title(title, meta.get('artist'))
        cov = None
        if meta.get('cover'):
            try: cov = write_cover(sid, meta['cover'])
            except Exception: pass
        now = int(time.time())
        with db() as c:
            c.execute("INSERT INTO songs (id,sync_id,title,artist,album,duration,file_path,cover_path,source,source_id,added_at,modified_at,album_id,track_num,play_count,last_played) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (sid, sync_id, title, meta.get('artist'), meta.get('album'), meta.get('duration'),
                 dest, cov, 'local', None, now, now, None, 0, 0, None))
        _stats_link_song(sid, meta.get('artist') or '', title)
        results.append({'song_id':sid,'title':title})

        def _analyze_and_save(fp=dest, so=sid):
            lufs = _analyze_loudness(fp)
            with db() as c:
                if lufs is not None:
                    c.execute("UPDATE songs SET loudness_lufs=? WHERE id=?", (lufs, so))
        _analysis_pool.submit(_analyze_and_save)
    with _cfg_lock:
        tok = CFG.get('genius_token', '')
        _auto_genius = CFG.get('auto_genius', True)
    if tok and _auto_genius:
        for res in results:
            threading.Thread(target=_genius_enrich, args=(res['song_id'], tok), daemon=True).start()
    return jsonify({'imported': results})

# ── dropbox sync ───────────────────────────────────────────────────────────────

import hashlib, time as _time

_DBX_APP_KEY    = 'joxlx0gp2umwf71'
_dbx_lock = threading.Lock()
_dbx_sync_thread = None
_dbx_stop = threading.Event()
_dbx_pkce_state = {}  # holds verifier + temp server ref during oauth flow

def _dbx():
    try:
        import dropbox
    except ImportError:
        return None
    tok = CFG.get('dropbox_refresh_token', '')
    _log_dbx.info(f'[dbx] tok={bool(tok)} cfg_id={id(CFG)}')
    if not tok:
        return None
    try:
        return dropbox.Dropbox(oauth2_refresh_token=tok, app_key=_DBX_APP_KEY)
    except Exception as e:
        _log_dbx.warning(f'[dbx] client init failed: {e}')
        return None

class DropboxQuotaError(Exception):
    pass

def _dbx_upload(dbx, local_path, remote_path):
    try:
        return _dbx_upload_raw(dbx, local_path, remote_path)
    except Exception as e:
        _s = str(e).lower()
        if 'insufficient_space' in _s or 'storage_limit' in _s or 'over_quota' in _s:
            raise DropboxQuotaError(str(e)) from e
        raise

def _dbx_upload_raw(dbx, local_path, remote_path):
    import dropbox
    local_path = Path(local_path)
    if not local_path.exists():
        return
    CHUNK = 128 * 1024 * 1024
    size  = local_path.stat().st_size
    with open(local_path, 'rb') as f:
        if size <= 150 * 1024 * 1024:
            dbx.files_upload(f.read(), remote_path,
                             mode=dropbox.files.WriteMode.overwrite, mute=True)
        else:
            sid    = dbx.files_upload_session_start(f.read(CHUNK)).session_id
            offset = CHUNK
            while offset < size:
                chunk  = f.read(CHUNK)
                cursor = dropbox.files.UploadSessionCursor(session_id=sid, offset=offset)
                offset += len(chunk)
                if offset >= size:
                    dbx.files_upload_session_finish(
                        chunk, cursor,
                        dropbox.files.CommitInfo(path=remote_path,
                                                 mode=dropbox.files.WriteMode.overwrite, mute=True))
                    return
                dbx.files_upload_session_append_v2(chunk, cursor)

def _dbx_remote_hash(dbx, remote_path):
    try:
        md = dbx.files_get_metadata(remote_path)
        return getattr(md, 'content_hash', None)
    except Exception:
        return None

def _dropbox_hash(path_or_data):
    """compute dropbox content hash. accepts a Path (streamed) or bytes (legacy)."""
    BLOCK = 4 * 1024 * 1024
    block_hashes = b''
    if isinstance(path_or_data, (str, Path)):
        with open(path_or_data, 'rb') as f:
            while True:
                chunk = f.read(BLOCK)
                if not chunk:
                    break
                block_hashes += hashlib.sha256(chunk).digest()
    else:
        data = path_or_data
        for i in range(0, len(data), BLOCK):
            block_hashes += hashlib.sha256(data[i:i+BLOCK]).digest()
    return hashlib.sha256(block_hashes).hexdigest()

def _dbx_pull_file(dbx, remote_path, local_path):
    try:
        _, res = dbx.files_download(remote_path)
        Path(local_path).parent.mkdir(parents=True, exist_ok=True)
        Path(local_path).write_bytes(res.content)
        return True
    except Exception as e:
        _log_dbx.warning(f'[dbx pull] failed {remote_path}: {e}')
        return False

def _record_sync_action(action, target, target2=None, payload=None, conn=None):
    row = (str(uuid.uuid4()), _dbx_get_device_id(), int(_time.time()), action,
           target, target2, json.dumps(payload) if payload is not None else None)
    if conn is not None:
        conn.execute(
            "INSERT INTO sync_actions (id,device_id,ts,action,target,target2,payload) "
            "VALUES (?,?,?,?,?,?,?)", row)
    else:
        with db() as c:
            c.execute(
                "INSERT INTO sync_actions (id,device_id,ts,action,target,target2,payload) "
                "VALUES (?,?,?,?,?,?,?)", row)

def _dbx_get_device_id():
    """get or generate a stable device_id, persisted in cfg."""
    did = CFG.get('device_id', '')
    if not did:
        with _cfg_lock:
            did = CFG.get('device_id', '')
            if not did:
                did = str(uuid.uuid4())
                CFG['device_id'] = did
                save_cfg(CFG)
    return did

def _dbx_get_device_name():
    """human-readable device name: cfg override or hostname."""
    name = CFG.get('device_name', '').strip()
    if not name:
        name = socket.gethostname() or 'unknown'
    return name

def _dbx_read_manifest(dbx, device_id):
    """download and parse a peer device manifest. returns dict or None."""
    try:
        _, res = dbx.files_download(f'/meowify/devices/{device_id}.json')
        return json.loads(res.content.decode())
    except Exception:
        return None

def _dbx_list_device_ids(dbx):
    """list all device_ids that have manifests in dropbox."""
    try:
        import dropbox as _dbxmod
        res = dbx.files_list_folder('/meowify/devices')
        ids = []
        while True:
            for entry in res.entries:
                if isinstance(entry, _dbxmod.files.FileMetadata) and entry.name.endswith('.json'):
                    ids.append(entry.name[:-5])
            if not res.has_more:
                break
            res = dbx.files_list_folder_continue(res.cursor)
        return ids
    except Exception:
        return []

def _dbx_push_manifest(dbx, extra_song_sync_ids=None, extra_cover_names=None):
    """build and upload this device's manifest to /meowify/devices/<device_id>.json."""
    import dropbox as _dbxmod
    device_id   = _dbx_get_device_id()
    device_name = _dbx_get_device_name()
    try:
        with db() as c:
            rows = c.execute('SELECT sync_id FROM songs WHERE sync_id IS NOT NULL').fetchall()
        song_sync_ids = list({r[0] for r in rows})
        _dbx_reconcile_availability()
        with db() as c:
            _arows = c.execute('SELECT sync_id FROM songs WHERE sync_id IS NOT NULL AND audio_available=1').fetchall()
        audio_sync_ids = list({r[0] for r in _arows})
        if extra_song_sync_ids:
            song_sync_ids = list(set(song_sync_ids) | set(extra_song_sync_ids))
        cover_names = [f.name for f in cdir().iterdir() if f.is_file()] if cdir().exists() else []
        if extra_cover_names:
            cover_names = list(set(cover_names) | set(extra_cover_names))
        local_db = db_path()
        manifest = {
            'device_id':     device_id,
            'device_name':   device_name,
            'last_seen':     int(_time.time()),
            'song_sync_ids': song_sync_ids,
            'audio_sync_ids': audio_sync_ids,
            'cover_names':   cover_names,
            'db_hash':       _dropbox_hash(local_db) if Path(local_db).exists() else _dropbox_hash(b''),
        }
        data = json.dumps(manifest).encode()
        dbx.files_upload(data, f'/meowify/devices/{device_id}.json',
                         mode=_dbxmod.files.WriteMode.overwrite, mute=True)
        return manifest
    except Exception as e:
        _log_dbx.warning(f'[dbx manifest] push failed: {e}')
        return None

_dbx_last_peer_manifests = []  # cached after each sync, used by status route

def _dbx_repair_path(p, search_dir, dbx=None, remote_folder=None):
    """Try to fix a single broken path. Three tiers, cheapest first:
      1. local rescue - the file is actually sitting right there under
         search_dir (mdir()/cdir()) but the stored path points at the wrong
         root (e.g. a peer's raw windows path leaked through an old
         _rebase_path bug, or any other root mismatch). Just repoint the
         column at the real local file - no network needed, fixes rows that
         were poisoned long before this function ever ran.
      2. targeted re-pull - file genuinely isn't local, but a dbx handle was
         passed in: ask dropbox directly for that exact filename instead of
         waiting on the next full sync's listing diff to (maybe) catch it.
      3. give up - return None, caller decides whether to null the column.
    Returns the corrected absolute path string, or None if unrecoverable."""
    if not p:
        return None
    name = Path(p).name
    # windows-style paths on linux/android don't split on backslash via
    # plain Path().name - extract the real basename defensively either way.
    if '\\' in name or ':' in name:
        from pathlib import PureWindowsPath
        name = PureWindowsPath(p).name
    if not name:
        return None

    local_candidate = Path(search_dir) / name
    if local_candidate.exists():
        return str(local_candidate)

    if dbx is not None and remote_folder:
        try:
            tmp = local_candidate.with_suffix(local_candidate.suffix + '.repair.tmp')
            if _dbx_pull_file(dbx, f'{remote_folder}/{name}', tmp):
                tmp.rename(local_candidate)
                _log_dbx.info(f'[dbx validate] repaired by re-pull: {name}')
                return str(local_candidate)
            tmp.unlink(missing_ok=True)
        except Exception as e:
            _log_dbx.info(f'[dbx validate] re-pull failed for {name}: {e}')

    return None

def _dbx_validate_paths(dbx=None):
    """Run once near the end of dbx_sync_now, after music/cover files have
    actually been pulled (steps 4-5). For every file_path/cover_path/image_path
    that doesn't exist on disk at the stored location, attempt auto-repair via
    _dbx_repair_path() before giving up:
      - if the file is actually present locally under the right dir (just the
        DB path is stale/wrong-root), repoint the column at it - this fixes
        rows poisoned by old bugs too, not just newly broken ones.
      - if a connected dbx handle is passed in and local rescue fails, try a
        direct targeted re-pull of that exact filename.
    Only if both fail does it fall back to the old behavior: cover/image
    columns get nulled (so the UI doesn't 404 on a dangling thumbnail),
    file_path is left alone since it's NOT NULL in schema and playback will
    surface the failure naturally. Returns counts for logging/status."""
    stale  = {'songs_file': 0, 'songs_cover': 0, 'albums_cover': 0, 'artists_image': 0}
    repaired = {'songs_file': 0, 'songs_cover': 0, 'albums_cover': 0, 'artists_image': 0}
    try:
        with db() as c:
            rows = c.execute("SELECT id, file_path, cover_path FROM songs").fetchall()
            for sid, fp, cp in rows:
                if fp and not Path(fp).exists():
                    fixed = _dbx_repair_path(fp, mdir(), dbx, '/meowify/music')
                    if fixed:
                        c.execute("UPDATE songs SET file_path=? WHERE id=?", (fixed, sid))
                        repaired['songs_file'] += 1
                        _log_dbx.info(f'[dbx validate] song {sid}: repaired file_path → {fixed}')
                    else:
                        _log_dbx.debug(f'[dbx validate] song {sid}: audio not on this device: {fp}')
                        # file_path is NOT NULL in schema - leave it; playback will
                        # surface the failure naturally and a future sync may fix it
                        # once the peer re-uploads under this name.
                if cp and not Path(cp).exists():
                    fixed = _dbx_repair_path(cp, cdir(), dbx, '/meowify/covers')
                    if fixed:
                        c.execute("UPDATE songs SET cover_path=? WHERE id=?", (fixed, sid))
                        repaired['songs_cover'] += 1
                    else:
                        _log_dbx.debug(f'[dbx validate] song {sid}: cover not on this device yet, keeping cover_path: {cp}')
            try:
                arows = c.execute("SELECT id, cover_path FROM albums").fetchall()
                for aid, cp in arows:
                    if cp and not Path(cp).exists():
                        fixed = _dbx_repair_path(cp, cdir(), dbx, '/meowify/covers')
                        if fixed:
                            c.execute("UPDATE albums SET cover_path=? WHERE id=?", (fixed, aid))
                            repaired['albums_cover'] += 1
                        else:
                            c.execute("UPDATE albums SET cover_path=NULL WHERE id=?", (aid,))
                            stale['albums_cover'] += 1
            except Exception as e:
                _log_dbx.warning(f'[dbx validate] albums cover repair failed: {e}')
            try:
                irows = c.execute("SELECT id, image_path FROM artists").fetchall()
                for aid, ip in irows:
                    if ip and not Path(ip).exists():
                        fixed = _dbx_repair_path(ip, cdir(), dbx, '/meowify/covers')
                        if fixed:
                            c.execute("UPDATE artists SET image_path=? WHERE id=?", (fixed, aid))
                            repaired['artists_image'] += 1
                        else:
                            c.execute("UPDATE artists SET image_path=NULL WHERE id=?", (aid,))
                            stale['artists_image'] += 1
            except Exception as e:
                _log_dbx.warning(f'[dbx validate] artists image repair failed: {e}')
    except Exception as e:
        _log_dbx.warning(f'[dbx validate] failed: {e}')
    if any(stale.values()) or any(repaired.values()):
        _log_dbx.info(f'[dbx validate] repaired: {repaired}  still stale: {stale}')
    return {**stale, 'repaired': repaired}

def _dbx_read_peer_manifests(dbx, own_device_id):
    """read all peer manifests in one pass, cache + return list of dicts."""
    global _dbx_last_peer_manifests
    peers = []
    for did in _dbx_list_device_ids(dbx):
        if did == own_device_id:
            continue
        m = _dbx_read_manifest(dbx, did)
        if m:
            peers.append(m)
    _dbx_last_peer_manifests = peers
    return peers

def _dbx_peer_song_sync_ids(dbx, own_device_id, peer_manifests=None):
    """union of song_sync_ids from all peer devices (excluding self)."""
    if peer_manifests is None:
        peer_manifests = _dbx_read_peer_manifests(dbx, own_device_id)
    return {sid for m in peer_manifests for sid in m.get('song_sync_ids', [])}

def _dbx_peer_cover_names(dbx, own_device_id, peer_manifests=None):
    """union of cover_names from all peer devices (excluding self)."""
    if peer_manifests is None:
        peer_manifests = _dbx_read_peer_manifests(dbx, own_device_id)
    return {n for m in peer_manifests for n in m.get('cover_names', [])}

_COVER_RESERVE = 64 * 1024 * 1024

def _dbx_reconcile_availability():
    try:
        with db() as c:
            rows = c.execute(
                "SELECT id, file_path, cover_path, audio_available, cover_available FROM songs").fetchall()
            for sid, fp, cp, aa, ca in rows:
                na = 1 if fp and Path(fp).exists() else 0
                nc = 1 if cp and Path(cp).exists() else 0
                if na != (aa or 0) or nc != (ca or 0):
                    c.execute("UPDATE songs SET audio_available=?, cover_available=? WHERE id=?",
                              (na, nc, sid))
    except Exception as e:
        _log_dbx.warning(f'[dbx reconcile] failed: {e}')

def _dbx_peer_audio_sets(peer_manifests):
    sets, legacy = [], False
    for m in peer_manifests:
        ids = m.get('audio_sync_ids')
        if ids is None:
            legacy = True
            ids = m.get('song_sync_ids', [])
        sets.append(set(ids))
    return sets, legacy

def _dbx_peer_cover_sets(peer_manifests):
    return [set(m.get('cover_names', [])) for m in peer_manifests]

def _dbx_needs_push(key, peer_sets, mode=None):
    mode = mode or CFG.get('dbx_push_mode', 'missing_on_peer')
    if not peer_sets:
        return False
    return any(key not in s for s in peer_sets)

def _dbx_space_budget(dbx):
    try:
        cap = max(1, min(100, int(CFG.get('dbx_quota_cap_pct', 80))))
    except Exception:
        cap = 80
    try:
        u = dbx.users_get_space_usage()
        a = u.allocation
        if a.is_individual():
            total = a.get_individual().allocated
        elif a.is_team():
            t = a.get_team()
            total = getattr(t, 'user_within_team_space_allocated', 0) or t.allocated
        else:
            total = 0
        if not total:
            return None, cap
        return int(total * cap / 100) - u.used, cap
    except Exception as e:
        _log_dbx.warning(f'[dbx space] usage check failed: {e}')
        return None, cap

def _dbx_cleanup_delivered(dbx, peer_manifests):
    import dropbox as _dbxmod
    if not peer_manifests:
        return 0, 0
    try:
        _expected = [i for i in _dbx_list_device_ids(dbx) if i != _dbx_get_device_id()]
        if len(_expected) != len(peer_manifests):
            return 0, 0
    except Exception:
        return 0, 0
    peer_audio, legacy = _dbx_peer_audio_sets(peer_manifests)
    if legacy:
        return 0, 0
    peer_covers = _dbx_peer_cover_sets(peer_manifests)

    def _list(folder):
        out = {}
        try:
            res = dbx.files_list_folder(folder)
            while True:
                for e in res.entries:
                    if isinstance(e, _dbxmod.files.FileMetadata):
                        out[e.name] = e.size
                if not res.has_more:
                    break
                res = dbx.files_list_folder_continue(res.cursor)
        except Exception:
            pass
        return out

    deleted = freed = 0
    try:
        with db() as c:
            rows = c.execute(
                "SELECT file_path, sync_id FROM songs WHERE sync_id IS NOT NULL AND audio_available=1").fetchall()
        have_audio = {Path(fp).name: sid for fp, sid in rows if fp}
        for name, size in _list('/meowify/music').items():
            sid = have_audio.get(name)
            if sid and all(sid in s for s in peer_audio):
                try:
                    dbx.files_delete_v2(f'/meowify/music/{name}')
                    deleted += 1
                    freed += size or 0
                except Exception as e:
                    _log_dbx.warning(f'[dbx cleanup] delete {name}: {e}')
        local_covers = {f.name for f in cdir().iterdir() if f.is_file()} if cdir().exists() else set()
        for name, size in _list('/meowify/covers').items():
            if name in local_covers and all(name in s for s in peer_covers):
                try:
                    dbx.files_delete_v2(f'/meowify/covers/{name}')
                    deleted += 1
                    freed += size or 0
                except Exception as e:
                    _log_dbx.warning(f'[dbx cleanup] delete cover {name}: {e}')
    except Exception as e:
        _log_dbx.warning(f'[dbx cleanup] failed: {e}')
    if deleted:
        _log_dbx.info(f'[dbx cleanup] removed {deleted} delivered files, freed {freed} bytes')
    return deleted, freed

def dbx_sync_now(push_db=True, pull_db=True, push_songs=False, pull_songs=True,
                 sync_settings=True, status_cb=None):
    dbx = _dbx()
    if dbx is None:
        return {'error': 'dropbox not connected'}
    results = {'pushed': [], 'pulled': [], 'errors': []}
    device_id = _dbx_get_device_id()

    def _status(msg):
        if status_cb:
            status_cb(msg)

    remote_db = '/meowify/library.db'
    local_db  = db_path()

    _dbx_prog_reset()

    # ── 0. settings sync (before library so cfg is live during rest) ──────────
    if sync_settings:
        try:
            _status('syncing settings...')
            if _dbx_pull_prefs(dbx):
                results['pulled'].append('prefs.json')
            if _dbx_push_prefs(dbx):
                results['pushed'].append('prefs.json')
        except Exception as e:
            results['errors'].append(f'settings sync: {e}')

    # ── 1. pull + merge db first (fixes push-before-pull race) ───────────────
    _remote_db_hash_after_pull = None  # reused in step 2 to avoid second API call
    _db_merge_failed = False
    if pull_db:
        try:
            _status('checking remote library...')
            remote_hash = _dbx_remote_hash(dbx, remote_db)
            _remote_db_hash_after_pull = remote_hash
            if remote_hash:
                if _dropbox_hash(local_db) != remote_hash:
                    _status('merging remote library...')
                    tmp = Path(local_db).parent / 'library_remote.db'
                    if _dbx_pull_file(dbx, remote_db, tmp):
                        _backup_daily()
                        _merge_ok = _dbx_merge_db(local_db, tmp)
                        tmp.unlink(missing_ok=True)
                        if _merge_ok is False:
                            _db_merge_failed = True
                            results['errors'].append('db merge failed or was skipped (low storage?) and nothing was changed; library upload skipped (see [dbx merge] in the log)')
                        else:
                            results['pulled'].append('library.db')
                        _remote_db_hash_after_pull = None  # merged locally, remote is now stale
        except Exception as e:
            results['errors'].append(f'db pull: {e}')

    # ── 1b. pull + apply peer action logs ────────────────────────────────────
    # runs after db merge so delete-wins actions override anything that merge
    # just re-inserted, and before push so this device's copy is correct
    # before re-uploading.
    try:
        _status('syncing actions...')
        applied = _dbx_pull_actions(dbx, device_id)
        if applied:
            results['pulled'].append(f'actions:{len(applied)}')
    except Exception as e:
        results['errors'].append(f'actions pull: {e}')

    # signal JS that db is merged - file downloads haven't started yet
    global _dbx_db_ready
    _dbx_db_ready = True

    # ── 2. push merged db (skip if remote was already identical) ──────────────
    if push_db:
        try:
            local_hash_now = _dropbox_hash(local_db) if Path(local_db).exists() else _dropbox_hash(b'')
            # reuse hash from step 1 if available (saves one API round-trip)
            known_remote = _remote_db_hash_after_pull if _remote_db_hash_after_pull is not None \
                           else _dbx_remote_hash(dbx, remote_db)
            if local_hash_now != known_remote and not _db_merge_failed:
                # run lightweight integrity cleanup before upload so peers don't
                # inherit duplicate album_tracks rows or stale pref_reset storms
                try:
                    _dedupe_album_tracks()
                    _cleanup_sync_actions()
                except Exception as _ce:
                    _log_dbx.warning('pre-upload cleanup err: %s', _ce)
                _status('uploading library...')
                _dbx_upload(dbx, local_db, remote_db)
                results['pushed'].append('library.db')
            with _cfg_lock:
                CFG['dropbox_last_sync'] = int(_time.time())
                save_cfg(CFG)
        except Exception as e:
            results['errors'].append(f'db push: {e}')

    # ── 2b. push this device's own new actions ────────────────────────────────
    try:
        if _dbx_push_actions(dbx):
            results['pushed'].append('actions')
    except Exception as e:
        results['errors'].append(f'actions push: {e}')

    # publish the manifest early so peers see this device's state before any
    # media transfer starts (a long upload/download no longer delays it)
    try:
        _status('updating device manifest...')
        _dbx_push_manifest(dbx)
    except Exception as e:
        results['errors'].append(f'manifest push: {e}')

    # ── 3. read peer manifests once for file sync decisions ───────────────────
    # always fetch — peer_song_ids must be populated before the auto-push loop
    # or every local song would be re-uploaded on every sync cycle
    peer_song_ids  = set()
    peer_cover_set = set()
    peer_manifests = []
    try:
        _status('reading device manifests...')
        peer_manifests = _dbx_read_peer_manifests(dbx, device_id)
        peer_song_ids  = _dbx_peer_song_sync_ids(dbx, device_id, peer_manifests)
        peer_cover_set = _dbx_peer_cover_names(dbx, device_id, peer_manifests)
    except Exception as e:
        results['errors'].append(f'manifest read: {e}')

    try:
        _dbx_reconcile_availability()
    except Exception as e:
        results['errors'].append(f'availability: {e}')
    _peer_audio, _legacy_peer = _dbx_peer_audio_sets(peer_manifests)
    _peer_covers = _dbx_peer_cover_sets(peer_manifests)
    _have_peers = bool(peer_manifests)
    _budget, _cap_pct = None, 80

    # ── 4. music files ────────────────────────────────────────────────────────
    pushed_song_sync_ids = []
    if pull_songs or push_songs:
        try:
            _status('syncing music files...')
            if _have_peers:
                _dbx_cleanup_delivered(dbx, peer_manifests)
            _budget, _cap_pct = _dbx_space_budget(dbx)
            import dropbox as _dbxmod
            try:
                remote_files = {}
                remote_sizes = {}
                res = dbx.files_list_folder('/meowify/music')
                while True:
                    for entry in res.entries:
                        if isinstance(entry, _dbxmod.files.FileMetadata):
                            remote_files[entry.name] = entry.content_hash
                            remote_sizes[entry.name] = entry.size
                    if not res.has_more:
                        break
                    res = dbx.files_list_folder_continue(res.cursor)
            except Exception as _rfe:
                remote_files = {}
                results['errors'].append(f'music list: {_rfe}')

            local_songs = {f.name: f for f in mdir().iterdir() if f.is_file()} if mdir().exists() else {}

            # auto-push: upload any local song not yet on dropbox or not yet
            # known to any peer device. push_songs no longer bypasses the peer
            # check: force sync and auto sync both only push what a peer lacks.
            with db() as c:
                rows = c.execute('SELECT file_path, sync_id FROM songs WHERE sync_id IS NOT NULL').fetchall()
            fname_to_syncid = {Path(r[0]).name: r[1] for r in rows if r[0]}

            # pre-compute the actual pending set (post-skip-check) so the
            # checklist UI gets an accurate n/x total instead of the full
            # remote/local listing size which would include already-synced items
            _push_pending = []
            _skipped_cap = 0
            _music_budget = None if _budget is None else max(0, _budget - _COVER_RESERVE)
            with db() as c:
                _added = {Path(r[0]).name: (r[1] or 0) for r in c.execute(
                    "SELECT file_path, added_at FROM songs WHERE file_path IS NOT NULL AND file_path != ''").fetchall()}
            _cands = []
            for name, fpath in local_songs.items():
                sync_id = fname_to_syncid.get(name)
                if not (sync_id and _dbx_needs_push(sync_id, _peer_audio)):
                    continue
                try:
                    _sz = fpath.stat().st_size
                except OSError:
                    continue
                if name in remote_files and remote_sizes.get(name) == _sz:
                    continue
                _cands.append((_added.get(name, 0), name, fpath, sync_id, _sz))
            _cands.sort(key=lambda t: t[0], reverse=True)
            for _ad, name, fpath, sync_id, _sz in _cands:
                if _music_budget is not None:
                    if _sz > _music_budget:
                        _skipped_cap += 1
                        continue
                    _music_budget -= _sz
                _push_pending.append((name, fpath, sync_id))
            if _skipped_cap:
                results['paused'] = f'{_skipped_cap} songs waiting, dropbox over {_cap_pct}% cap'
                _status(results['paused'])

            with db() as c:
                _fname_to_sid = {Path(fp).name: sid for fp, sid in
                                  c.execute("SELECT file_path, id FROM songs WHERE file_path IS NOT NULL AND file_path != ''").fetchall()} \
                                if pull_songs else {}
            _pull_pending = []
            if pull_songs:
                with db() as c:
                    _want_names = {Path(r[0]).name for r in c.execute(
                        "SELECT file_path FROM songs WHERE file_path IS NOT NULL AND file_path != '' AND audio_available=0").fetchall()}
                for name, rhash in remote_files.items():
                    if name in _want_names and not (mdir() / name).exists():
                        _pull_pending.append((name, rhash))

            _dbx_prog_init('tracks', [n for n, _, _ in _push_pending] + [n for n, _ in _pull_pending])

            _push_fail = 0
            for name, fpath, sync_id in _push_pending:
                _status(f'uploading {name}...')
                try:
                    _dbx_upload(dbx, fpath, f'/meowify/music/{name}')
                except DropboxQuotaError as _qe:
                    results['paused'] = 'dropbox storage full'
                    results['errors'].append(f'upload stopped: {_qe}')
                    break
                except Exception as _ue:
                    _push_fail += 1
                    results['errors'].append(f'upload {name}: {_ue}')
                    _dbx_prog_tick('tracks', name)
                    if _push_fail >= 3:
                        break
                    continue
                results['pushed'].append(name)
                if sync_id:
                    pushed_song_sync_ids.append(sync_id)
                _dbx_prog_tick('tracks', name)

            for name, rhash in _pull_pending:
                local_path = mdir() / name
                # tie into the same download registry manual downloads use, so
                # the placeholder/downloading UI treats sync pulls identically -
                # only if the song row already exists (normal case: db merge ran
                # first in step 1), otherwise fall through with no live placeholder
                _sync_sid = _fname_to_sid.get(name)
                _sync_did = f'sync-{_sync_sid}' if _sync_sid else None
                if _sync_did:
                    with _dl_lock:
                        _dls[_sync_did] = {'status': 'downloading', 'progress': 10, 'error': None,
                                            'song_id': _sync_sid, 'query': name, 'source': 'sync'}
                _status(f'downloading {name}...')
                tmp = local_path.with_suffix(local_path.suffix + '.tmp')
                if _dbx_pull_file(dbx, f'/meowify/music/{name}', tmp):
                    tmp.rename(local_path)
                    results['pulled'].append(name)
                    if _sync_did:
                        _dl(_sync_did, status='done', progress=100)
                else:
                    tmp.unlink(missing_ok=True)
                    if _sync_did:
                        _dl(_sync_did, status='error', error='pull failed')
                _dbx_prog_tick('tracks', name)
        except Exception as e:
            results['errors'].append(f'music sync: {e}')

    # re-publish after the music phase so peers see deliveries before the covers
    # phase and before the sync fully finishes
    if pushed_song_sync_ids or results['pulled']:
        try:
            _dbx_push_manifest(dbx, extra_song_sync_ids=pushed_song_sync_ids)
        except Exception as e:
            results['errors'].append(f'manifest push: {e}')

    # ── 5. covers ─────────────────────────────────────────────────────────────
    pushed_cover_names = []
    try:
        if pull_songs or push_songs:
            _status('syncing covers...')
            try:
                import dropbox as _dbxmod
                remote_covers = {}
                res = dbx.files_list_folder('/meowify/covers')
                while True:
                    for entry in res.entries:
                        if isinstance(entry, _dbxmod.files.FileMetadata):
                            remote_covers[entry.name] = entry.content_hash
                    if not res.has_more:
                        break
                    res = dbx.files_list_folder_continue(res.cursor)
            except Exception:
                remote_covers = {}

            local_covers = {f.name: f for f in cdir().iterdir() if f.is_file()} if cdir().exists() else {}

            _ref = set()
            with db() as c:
                for _q in ("SELECT cover_path FROM songs",
                           "SELECT cover_path FROM albums",
                           "SELECT image_path FROM artists"):
                    try:
                        _ref |= {Path(r[0]).name for r in c.execute(_q).fetchall() if r[0]}
                    except Exception:
                        pass
            _cover_push_pending = []
            _cb = _budget
            if _have_peers:
                for name, fpath in local_covers.items():
                    if not (name in _ref and _dbx_needs_push(name, _peer_covers)):
                        continue
                    if remote_covers.get(name) == _dropbox_hash(fpath):
                        continue  # already on dropbox and identical, skip
                    if _cb is not None:
                        _csz = fpath.stat().st_size
                        if _csz > _cb:
                            continue
                        _cb -= _csz
                    _cover_push_pending.append((name, fpath))

            _cover_pull_pending = []
            if pull_songs:
                for name, rhash in remote_covers.items():
                    local_path = cdir() / name
                    if name in _ref and not local_path.exists():
                        _cover_pull_pending.append((name, local_path))

            _dbx_prog_init('covers', [n for n, _ in _cover_push_pending] + [n for n, _ in _cover_pull_pending])

            for name, fpath in _cover_push_pending:
                try:
                    _dbx_upload(dbx, fpath, f'/meowify/covers/{name}')
                except DropboxQuotaError as _qe:
                    results['paused'] = 'dropbox storage full'
                    results['errors'].append(f'cover upload stopped: {_qe}')
                    break
                results['pushed'].append(f'cover:{name}')
                pushed_cover_names.append(name)
                _dbx_prog_tick('covers', name)

            for name, local_path in _cover_pull_pending:
                _dbx_pull_file(dbx, f'/meowify/covers/{name}', local_path)
                results['pulled'].append(f'cover:{name}')
                _dbx_prog_tick('covers', name)
    except Exception as e:
        results['errors'].append(f'covers: {e}')

    # ── 5b. validate paths now that file sync has actually run ───────────────
    try:
        _status('checking files...')
        stale = _dbx_validate_paths()
        _dbx_reconcile_availability()
        if results['pulled'] and _have_peers:
            _dbx_cleanup_delivered(dbx, peer_manifests)
        if any(stale[k] for k in stale if k != 'repaired') or any(stale['repaired'].values()):
            results['stale_cleared'] = stale
    except Exception as e:
        results['errors'].append(f'path validate: {e}')

    # ── 6. push updated manifest for this device ──────────────────────────────
    try:
        _status('updating device manifest...')
        _dbx_push_manifest(dbx,
                           extra_song_sync_ids=pushed_song_sync_ids,
                           extra_cover_names=pushed_cover_names)
    except Exception as e:
        results['errors'].append(f'manifest push: {e}')

    _status('done')
    return results

# keys that are safe to share across devices via dropbox prefs sync.
# explicitly excludes: data_dir, spotify_local_dir (path-local),
# dropbox_refresh_token, dropbox_sync_enabled, dropbox_last_sync,
# device_id, device_name (per-device identity),
# sync_library, sync_settings (each device opts in independently).
_DBX_SHARED_PREFS = frozenset([
    'gapless', 'format', 'quality', 'crossfade',
    'genius_token', 'auto_genius', 'ddg_genius',
    'volume_norm', 'target_lufs',
    'theme_hue', 'theme_sat', 'theme_bri',
    'prev_restarts', 'dl_speed_single', 'dl_speed_batch',
    'auto_align_lyrics', 'ui_design', 'glass_alpha', 'glass_blur',
    'volume', 'volume_boost', 'eq', 'enhance_audio', 'immersive_audio',
])

def _dbx_push_prefs(dbx):
    """upload shared settings to /meowify/prefs.json.
    skips push if all local shared prefs are still at factory defaults
    (fresh install shouldn't clobber an established device's settings)."""
    import dropbox as _dbxmod
    try:
        with _cfg_lock:
            prefs = {k: CFG[k] for k in _DBX_SHARED_PREFS if k in CFG}
        if all(prefs.get(k) == _DEFS.get(k) for k in _DBX_SHARED_PREFS if k in _DEFS):
            _log_dbx.info('[dbx prefs] skipping push - all values are defaults')
            return False
        prefs['_modified'] = CFG.get('_prefs_modified', int(_time.time()))
        data = json.dumps(prefs).encode()
        dbx.files_upload(data, '/meowify/prefs.json',
                         mode=_dbxmod.files.WriteMode.overwrite, mute=True)
        return True
    except Exception as e:
        _log_dbx.warning(f'[dbx prefs] push failed: {e}')
        return False

def _dbx_pull_prefs(dbx):
    """download /meowify/prefs.json and merge shared keys into local cfg.

    Per-key merge instead of whole-blob last-write-wins: a key is only pulled
    from remote if the LOCAL value for that key is still at its factory default
    (i.e. the user hasn't customized it on this device). This prevents the old
    behaviour where a single stale/clock-skewed timestamp on ANY one device
    could silently overwrite a user's deliberately-changed settings (genius
    token, theme, eq, volume, etc.) on every 5-minute background sync cycle.
    Per-device-customized keys are never clobbered by sync; only "still default"
    keys are ever filled in from a peer.

    Exception: "still at default" is ambiguous between "never touched" and
    "deliberately reset back to default". a pref_reset sync_action records the
    latter explicitly. if the most recent pref_reset for a key is newer than
    remote's _modified, keep the default - the user chose it on purpose more
    recently than whatever's in prefs.json. note: on the very cycle where a
    peer's pref_reset is first pulled (step 1b, after this step 0 runs), this
    check is a no-op since the action isn't in local sync_actions yet - but
    _dbx_apply_pref_reset in step 1b corrects it within the same sync run."""
    try:
        _, res = dbx.files_download('/meowify/prefs.json')
        remote = json.loads(res.content.decode())
    except Exception:
        return False
    remote_ts = remote.get('_modified', 0)
    with db() as c:
        reset_rows = c.execute(
            "SELECT target, MAX(ts) FROM sync_actions WHERE action='pref_reset' GROUP BY target"
        ).fetchall()
    last_reset = {r[0]: r[1] for r in reset_rows}
    changed = {}
    with _cfg_lock:
        for k, v in remote.items():
            if k not in _DBX_SHARED_PREFS:
                continue
            local_val = CFG.get(k)
            if local_val == v:
                continue
            is_local_default = k in _DEFS and local_val == _DEFS.get(k)
            if not is_local_default:
                continue
            if last_reset.get(k, 0) > remote_ts:
                continue  # deliberately reset more recently than this remote value
            CFG[k] = v
            changed[k] = v
        if changed:
            CFG['_prefs_modified'] = max(CFG.get('_prefs_modified', 0), remote_ts or int(_time.time()))
            save_cfg(CFG)
            _log_dbx.info(f'[dbx prefs] pulled {list(changed.keys())} (were still at defaults locally)')
    return bool(changed)

def _dbx_fix_song_artist_rows(c, cols, rows, remap):
    """remap artist ids that were skipped because the same artist already exists
    locally under a different id, and drop rows whose song/artist doesn't exist
    locally (tombstoned songs etc) so they can't trip the foreign keys."""
    if 'song_id' not in cols or 'artist_id' not in cols:
        return rows
    si, ai = cols.index('song_id'), cols.index('artist_id')
    songs_ok   = {r[0] for r in c.execute('SELECT id FROM songs')}
    artists_ok = {r[0] for r in c.execute('SELECT id FROM artists')}
    out = []
    for row in rows:
        row = list(row)
        row[ai] = remap.get(row[ai], row[ai])
        if row[si] in songs_ok and row[ai] in artists_ok:
            out.append(tuple(row))
    return out

_DBX_FK_PARENTS = {
    'lyrics':         (('song_id', 'songs'),),
    'album_tracks':   (('album_id', 'albums'),),
    'playlist_songs': (('playlist_id', 'playlists'), ('song_id', 'songs')),
    'play_events':    (('song_stats_id', 'song_stats'),),
}

def _dbx_drop_orphans(c, tbl, cols, rows):
    """drop incoming rows whose parent row isn't present locally (tombstoned songs,
    albums deleted here, ...). foreign_keys is ON during the merge, and one such row
    would otherwise abort the whole transaction."""
    checks = []
    for col, parent in _DBX_FK_PARENTS.get(tbl, ()):
        if col in cols:
            checks.append((cols.index(col), {r[0] for r in c.execute(f'SELECT id FROM {parent}')}))
    if not checks:
        return rows
    kept = [row for row in rows if all(row[i] is None or row[i] in ids for i, ids in checks)]
    if len(kept) != len(rows):
        _log_dbx.info(f'[dbx merge] {tbl}: skipped {len(rows) - len(kept)} rows whose parent row is not present locally')
    return kept

def _dbx_merge_db(local_path, remote_path):
    """returns True when the merge was applied, False when it failed and was rolled back."""
    import sqlite3 as _sq
    _merge_ok = True
    try:
        _need_merge = os.path.getsize(str(remote_path)) * 2
    except Exception:
        _need_merge = 0
    if not _free_space_ok(Path(local_path).parent, _need_merge, 'dbx merge', _log_dbx):
        return False
    # read all rows from remote into memory first, then write to local via the
    # WAL-safe db() context manager so we don't race with flask writes
    try:
        rem = _sq.connect(str(remote_path))
        rem.row_factory = _sq.Row
        rc = rem.cursor()
        tables_data = {}
        for tbl in ('songs', 'song_stats', 'play_events', 'playlists', 'playlist_songs',
                    'albums', 'artists', 'song_artists', 'album_tracks', 'lyrics'):
            try:
                rc.execute(f'SELECT * FROM {tbl}')
                rows = rc.fetchall()
                if rows:
                    cols = list(rows[0].keys())
                    tables_data[tbl] = (cols, [tuple(r) for r in rows])
            except Exception as _te:
                _log_dbx.debug(f'[dbx merge] read table err: {_te}')
        rem.close()
    except Exception as e:
        _log_dbx.warning(f'[dbx merge] read remote: {e}')
        return False

    local_music_dir  = str(mdir())
    local_cover_dir  = str(cdir())

    def _rebase_path(p, local_dir):
        """Replace whatever base dir is in the remote path with the local one,
        keeping only the filename. NOTE: this runs before music/cover files are
        pulled (steps 4-5 in dbx_sync_now), so we can't check existence here -
        a file that's missing right now may land moments later. See
        _dbx_validate_paths(), called at the end of dbx_sync_now, which does
        the actual existence check once file sync has had a chance to run."""
        if not p:
            return p
        # Path(p).name fails for windows-style paths on Linux/Android because
        # pathlib treats the whole string as one component (no forward slashes).
        # Use PureWindowsPath to extract the filename correctly regardless of
        # which OS the syncing peer wrote the path on.
        #
        # Only do this when the string actually looks like a Windows path
        # (drive letter "C:\" or UNC "\\server\share") - a plain backslash
        # anywhere in the string isn't enough evidence, since a Linux/Android
        # filename can legitimately contain a literal backslash character.
        # Blindly running PureWindowsPath on any backslash-containing string
        # would silently truncate such a filename down to whatever followed
        # the last backslash.
        import re as _re_rebase
        looks_windows = bool(_re_rebase.match(r'^[A-Za-z]:[\\/]', p)) or p.startswith('\\\\')
        fname = None
        if looks_windows:
            from pathlib import PureWindowsPath
            fname = PureWindowsPath(p).name
        if not fname or fname == p:
            from pathlib import PurePosixPath
            fname = PurePosixPath(p).name
        return str(Path(local_dir) / fname)

    # this merge can run a large multi-table write transaction; the shared
    # db() helper's default 10s busy timeout is tuned for normal short-lived
    # Flask request writes, not this. Use our own connection with a longer
    # busy timeout so concurrent app writes don't get database-is-locked'd
    # mid-sync, and so we don't hold up app writes longer than necessary.
    try:
        _conn = sqlite3.connect(str(db_path()), timeout=30)
        _conn.row_factory = sqlite3.Row
        _conn.execute("PRAGMA temp_store=MEMORY")
        _conn.execute("PRAGMA journal_mode=WAL")
        _conn.execute("PRAGMA foreign_keys=ON")
        _conn.create_function('_canonical', 1, _canonical)
        _conn.create_function('_ulower', 1, _ulower, deterministic=True)
        c = _conn
        with _conn:
            _artist_remap = {}
            for tbl, (cols, rows) in tables_data.items():
                # strip any columns the remote db has that don't exist in local schema
                # (avoids hard failures when schemas diverge across devices/versions)
                try:
                    _local_cols = {r[1] for r in c.execute(f'PRAGMA table_info({tbl})').fetchall()}
                except Exception:
                    _local_cols = set(cols)
                if _local_cols and not _local_cols.issuperset(cols):
                    _keep = [i for i, col in enumerate(cols) if col in _local_cols]
                    _dropped = [cols[i] for i in range(len(cols)) if i not in _keep]
                    _log_dbx.info(f'[dbx merge] dropping unknown cols from {tbl}: {_dropped}')
                    cols = [cols[i] for i in _keep]
                    rows = [tuple(row[i] for i in _keep) for row in rows]
                if tbl == 'songs' and ({'audio_available', 'cover_available'} & set(cols)):
                    _keep = [i for i, col in enumerate(cols) if col not in ('audio_available', 'cover_available')]
                    cols = [cols[i] for i in _keep]
                    rows = [tuple(row[i] for i in _keep) for row in rows]
                placeholders = ','.join(['?'] * len(cols))
                col_str      = ','.join(cols)
                if tbl in _DBX_FK_PARENTS:
                    rows = _dbx_drop_orphans(c, tbl, cols, rows)
                if tbl == 'songs':
                    syncid_idx = cols.index('sync_id')     if 'sync_id'     in cols else None
                    modat_idx  = cols.index('modified_at') if 'modified_at' in cols else None
                    fp_idx     = cols.index('file_path')   if 'file_path'   in cols else None
                    cp_idx     = cols.index('cover_path')  if 'cover_path'  in cols else None
                    # skip rows with a local song_delete action at or after their
                    # modified_at. on the very first sync after a peer's delete
                    # this is a no-op (peer's action hasn't been pulled into our
                    # sync_actions yet - that happens in step 1b, after this merge),
                    # but step 1b's _dbx_apply_song_delete corrects it anyway.
                    # from the second sync onward this gate stops the upsert from
                    # re-inserting the row in the first place.
                    if syncid_idx is not None:
                        del_rows = c.execute(
                            "SELECT target, MAX(ts) FROM sync_actions "
                            "WHERE action='song_delete' GROUP BY target").fetchall()
                        deleted_ts = {r[0]: r[1] for r in del_rows}
                    else:
                        deleted_ts = {}
                    src_idx = cols.index('source') if 'source' in cols else None
                    _batched_rows = []
                    for row in rows:
                        row = list(row)
                        if src_idx is not None and row[src_idx] == 'downloading' and (fp_idx is None or not row[fp_idx]):
                            continue
                        if syncid_idx is not None and row[syncid_idx] in deleted_ts:
                            row_modat = row[modat_idx] if modat_idx is not None else None
                            if row_modat is None or deleted_ts[row[syncid_idx]] >= row_modat:
                                continue
                        if fp_idx is not None and row[fp_idx]:
                            row[fp_idx] = _rebase_path(row[fp_idx], local_music_dir)
                        if cp_idx is not None and row[cp_idx]:
                            row[cp_idx] = _rebase_path(row[cp_idx], local_cover_dir)
                        _batched_rows.append(row)
                    c.executemany(
                        f'INSERT INTO songs ({col_str}) VALUES ({placeholders}) '
                        f'ON CONFLICT(id) DO UPDATE SET '
                        f'title=excluded.title, artist=excluded.artist, album=excluded.album, '
                        f'file_path=COALESCE(excluded.file_path, songs.file_path), '
                        f'cover_path=COALESCE(excluded.cover_path, songs.cover_path), '
                        f'genius_id=excluded.genius_id, '
                        f'featuring_artists=excluded.featuring_artists, '
                        f'loudness_lufs=excluded.loudness_lufs, '
                        f'album_id=excluded.album_id, track_num=excluded.track_num, '
                        f'mv_video_id=COALESCE(excluded.mv_video_id, songs.mv_video_id), mv_offset=COALESCE(excluded.mv_offset, songs.mv_offset), '\
                        f'{"spotify_url=COALESCE(excluded.spotify_url, songs.spotify_url), " if "spotify_url" in cols else ""}'\
                        f'{"queue_skip=excluded.queue_skip, " if "queue_skip" in cols else ""}'\
                        f'modified_at=excluded.modified_at '
                        f'WHERE excluded.modified_at IS NOT NULL '
                        f'AND (songs.modified_at IS NULL OR excluded.modified_at > songs.modified_at)',
                        _batched_rows
                    )
                elif tbl == 'song_stats':
                    # insert stub rows only; counters recomputed below from play_events
                    c.executemany(
                        f'INSERT OR IGNORE INTO song_stats ({col_str}) VALUES ({placeholders})',
                        rows
                    )
                elif tbl == 'playlists':
                    syncid_idx = cols.index('sync_id')     if 'sync_id'     in cols else None
                    modat_idx  = cols.index('modified_at') if 'modified_at' in cols else None
                    if syncid_idx is not None:
                        del_rows = c.execute(
                            "SELECT target, MAX(ts) FROM sync_actions "
                            "WHERE action='pl_delete' GROUP BY target").fetchall()
                        deleted_ts = {r[0]: r[1] for r in del_rows}
                    else:
                        deleted_ts = {}
                    rows = [row for row in rows
                            if not (syncid_idx is not None
                                    and row[syncid_idx] in deleted_ts
                                    and (modat_idx is None or row[modat_idx] is None
                                         or deleted_ts[row[syncid_idx]] >= row[modat_idx]))]
                    c.executemany(
                        f'INSERT INTO playlists ({col_str}) VALUES ({placeholders}) '
                        f'ON CONFLICT(id) DO UPDATE SET '
                        f'name=excluded.name, modified_at=excluded.modified_at '
                        f'WHERE excluded.modified_at IS NOT NULL '
                        f'AND (playlists.modified_at IS NULL OR excluded.modified_at > playlists.modified_at)',
                        rows
                    )
                elif tbl == 'albums':
                    id_idx = cols.index('id') if 'id' in cols else None
                    cp_idx = cols.index('cover_path') if 'cover_path' in cols else None
                    # album_delete tombstones: skip any incoming album row whose
                    # id was deleted locally - otherwise a peer that hasn't yet
                    # pulled that delete will just re-upload the row forever.
                    del_rows = c.execute(
                        "SELECT target, MAX(ts) FROM sync_actions "
                        "WHERE action='album_delete' GROUP BY target").fetchall()
                    deleted_ts = {r[0]: r[1] for r in del_rows}
                    _batched_rows = []
                    for row in rows:
                        row = list(row)
                        if id_idx is not None and row[id_idx] in deleted_ts:
                            continue
                        if cp_idx is not None and row[cp_idx]:
                            row[cp_idx] = _rebase_path(row[cp_idx], local_cover_dir)
                        _batched_rows.append(row)
                    if _batched_rows:
                        c.executemany(
                            f'INSERT INTO albums ({col_str}) VALUES ({placeholders}) '
                            f'ON CONFLICT(id) DO UPDATE SET '
                            f'cover_path=COALESCE(albums.cover_path, excluded.cover_path), '
                            f'genius_id=COALESCE(albums.genius_id, excluded.genius_id), '
                            f'deezer_id=COALESCE(albums.deezer_id, excluded.deezer_id), '
                            f'year=COALESCE(albums.year, excluded.year)',
                            _batched_rows
                        )
                    if deleted_ts:
                        c.executemany("DELETE FROM albums WHERE id=?",
                                      [(k,) for k in deleted_ts])
                elif tbl == 'artists':
                    id_idx = cols.index('id') if 'id' in cols else None
                    ip_idx = cols.index('image_path') if 'image_path' in cols else None
                    nm_idx = cols.index('name') if 'name' in cols else None
                    _local_by_name = {}
                    if nm_idx is not None:
                        for _lid, _lnm in c.execute("SELECT id, name FROM artists").fetchall():
                            _local_by_name.setdefault(_ulower(_lnm), _lid)
                    del_rows = c.execute(
                        "SELECT target, MAX(ts) FROM sync_actions "
                        "WHERE action='artist_delete' GROUP BY target").fetchall()
                    deleted_ts = {r[0]: r[1] for r in del_rows}
                    _batched_rows = []
                    for row in rows:
                        row = list(row)
                        if id_idx is not None and row[id_idx] in deleted_ts:
                            continue
                        if nm_idx is not None and id_idx is not None:
                            # unique index on lower(name): an artist the other device
                            # created independently has a different id but the same name.
                            # keep the local row and remap references instead of letting
                            # the unique violation roll back the whole merge.
                            _key = _ulower(row[nm_idx])
                            _existing = _local_by_name.get(_key)
                            if _existing is not None and _existing != row[id_idx]:
                                _artist_remap[row[id_idx]] = _existing
                                continue
                            _local_by_name[_key] = row[id_idx]
                        if ip_idx is not None and row[ip_idx]:
                            row[ip_idx] = _rebase_path(row[ip_idx], local_cover_dir)
                        _batched_rows.append(row)
                    if _batched_rows:
                        c.executemany(
                            f'INSERT INTO artists ({col_str}) VALUES ({placeholders}) '
                            f'ON CONFLICT(id) DO UPDATE SET '
                            f'ytm_channel_id=COALESCE(artists.ytm_channel_id, excluded.ytm_channel_id), '
                            f'genius_artist_id=COALESCE(artists.genius_artist_id, excluded.genius_artist_id), '
                            f'image_path=COALESCE(artists.image_path, excluded.image_path), '
                            f'bio=COALESCE(artists.bio, excluded.bio)',
                            _batched_rows
                        )
                    if deleted_ts:
                        c.executemany("DELETE FROM artists WHERE id=?",
                                      [(k,) for k in deleted_ts])
                elif tbl == 'playlist_songs':
                    # propagate position updates (reorders) from remote;
                    # remote wins on conflict since playlists use modified_at-based merge
                    c.executemany(
                        f'INSERT INTO playlist_songs ({col_str}) VALUES ({placeholders}) '
                        f'ON CONFLICT(playlist_id, song_id) DO UPDATE SET '
                        f'position=excluded.position',
                        rows
                    )
                elif tbl == 'lyrics':
                    # lyrics can be corrected/re-synced - last-write-wins by fetched_at
                    fi = cols.index('fetched_at') if 'fetched_at' in cols else None
                    c.executemany(
                        f'INSERT INTO lyrics ({col_str}) VALUES ({placeholders}) '
                        f'ON CONFLICT(song_id) DO UPDATE SET '
                        f'lrc=excluded.lrc, plain=excluded.plain, source=excluded.source, '
                        f'source_duration=excluded.source_duration, fetched_at=excluded.fetched_at '
                        f'WHERE excluded.fetched_at IS NOT NULL AND '
                        f'(lyrics.fetched_at IS NULL OR excluded.fetched_at > lyrics.fetched_at)',
                        rows
                    )
                elif tbl == 'album_tracks':
                    # deduplicate by (album_id, track_num) and (album_id, genius_song_id)
                    # rather than bare INSERT OR IGNORE on id — remote rows have different
                    # UUIDs so IGNORE only deduplicates exact id matches, causing the same
                    # track to accumulate on every sync
                    at_aid_idx   = cols.index('album_id')       if 'album_id'       in cols else None
                    at_tnum_idx  = cols.index('track_num')      if 'track_num'      in cols else None
                    at_gsid_idx  = cols.index('genius_song_id') if 'genius_song_id' in cols else None
                    at_sid_idx   = cols.index('song_id')        if 'song_id'        in cols else None
                    at_vid_idx   = cols.index('video_id')       if 'video_id'       in cols else None
                    at_gdat_idx  = cols.index('genius_data')    if 'genius_data'    in cols else None
                    at_title_idx = cols.index('title')          if 'title'          in cols else None
                    at_art_idx   = cols.index('artist')         if 'artist'         in cols else None
                    for row in rows:
                        aid    = row[at_aid_idx]   if at_aid_idx   is not None else None
                        tnum   = row[at_tnum_idx]  if at_tnum_idx  is not None else None
                        gsid   = row[at_gsid_idx]  if at_gsid_idx  is not None else None
                        sid_v  = row[at_sid_idx]   if at_sid_idx   is not None else None
                        vid    = row[at_vid_idx]    if at_vid_idx   is not None else None
                        gdat   = row[at_gdat_idx]  if at_gdat_idx  is not None else None
                        title_ = row[at_title_idx] if at_title_idx is not None else None
                        art_   = row[at_art_idx]   if at_art_idx   is not None else None
                        # try to find an existing row by genius_song_id first, then track_num
                        existing = None
                        if gsid:
                            existing = c.execute(
                                "SELECT id FROM album_tracks WHERE album_id=? AND genius_song_id=?",
                                (aid, gsid)).fetchone()
                        if not existing and tnum is not None:
                            existing = c.execute(
                                "SELECT id FROM album_tracks WHERE album_id=? AND track_num=? AND genius_song_id IS NULL",
                                (aid, tnum)).fetchone()
                        if existing:
                            c.execute(
                                "UPDATE album_tracks SET "
                                "song_id=COALESCE(song_id,?), genius_song_id=COALESCE(genius_song_id,?), "
                                "video_id=COALESCE(video_id,?), genius_data=COALESCE(genius_data,?) "
                                "WHERE id=?",
                                (sid_v, gsid, vid, gdat, existing[0]))
                        else:
                            c.execute(
                                f'INSERT OR IGNORE INTO album_tracks ({col_str}) VALUES ({placeholders})',
                                row)
                else:
                    # play_events, song_artists — union / ignore duplicates
                    if tbl == 'song_artists':
                        rows = _dbx_fix_song_artist_rows(c, cols, rows, _artist_remap)
                    c.executemany(
                        f'INSERT OR IGNORE INTO {tbl} ({col_str}) VALUES ({placeholders})',
                        rows
                    )
            # recompute denormalized counters from the now-merged play_events
            c.execute("""
                UPDATE song_stats SET
                    play_count   = (SELECT COUNT(*)      FROM play_events WHERE song_stats_id = song_stats.id),
                    last_played  = (SELECT MAX(timestamp) FROM play_events WHERE song_stats_id = song_stats.id),
                    first_played = (SELECT MIN(timestamp) FROM play_events WHERE song_stats_id = song_stats.id)
                WHERE EXISTS (SELECT 1 FROM play_events WHERE song_stats_id = song_stats.id)
            """)
            # propagate back to songs table denorm copy.
            # canonical_artist/title were built with _canonical() (lower + strip
            # leading the/a/an + strip ALL punctuation, not just periods/commas).
            # _canonical is registered as a SQL function on every db() connection
            # (see conn.create_function above), so call it directly here instead
            # of the old LOWER(TRIM(REPLACE(REPLACE(...)))) approximation, which
            # only stripped periods/commas and missed ampersands, apostrophes,
            # leading articles, etc. - causing songs with those characters to
            # show a stale/zero play_count on this device right after a merge,
            # until next played locally (which re-syncs via the real fuzzy
            # matcher in _stats_upsert). note: this is still an exact match on
            # the canonical key, not the fuzzy SequenceMatcher scoring used
            # elsewhere - genuine near-duplicate titles still rely on that
            # same next-play safety net, same as before this fix.
            c.execute("""
                UPDATE songs SET
                    play_count  = COALESCE((\
                        SELECT ss.play_count FROM song_stats ss
                        WHERE ss.canonical_artist = _canonical(TRIM(SUBSTR(songs.artist, 1,
                            CASE WHEN INSTR(songs.artist,',')>0 THEN INSTR(songs.artist,',')-1
                                 ELSE LENGTH(songs.artist) END)))
                          AND ss.canonical_title  = _canonical(songs.title)
                        LIMIT 1), songs.play_count),
                    last_played = COALESCE((\
                        SELECT ss.last_played FROM song_stats ss
                        WHERE ss.canonical_artist = _canonical(TRIM(SUBSTR(songs.artist, 1,
                            CASE WHEN INSTR(songs.artist,',')>0 THEN INSTR(songs.artist,',')-1
                                 ELSE LENGTH(songs.artist) END)))
                          AND ss.canonical_title  = _canonical(songs.title)
                        LIMIT 1), songs.last_played)
            """)
    except Exception as e:
        _log_dbx.warning(f'[dbx merge] write local: {e}')
        _merge_ok = False
    finally:
        try:
            _conn.close()
        except Exception:
            pass
    # rebuild song_artists for any songs that arrived via sync without going
    # through _upsert_song_artists (which is only called at download/enrich time).
    # also rekey any stats rows with full-artist canonical to primary-only, and
    # consolidate duplicate stats rows that accumulate when two devices play the
    # same song independently before syncing.
    try:
        with db() as c:
            _migrate_artists(c)
            _migrate_stats_canonical_artist(c)
            merge_duplicate_stats(c)
    except Exception as e:
        _log_dbx.warning(f'[dbx merge] post-merge migrations err: {e}')
    return _merge_ok

# ── action log: deletions / membership / pref-resets ─────────────────────────
# per-device append-only files on dropbox (/meowify/actions/<device_id>.jsonl)
# devices only ever append to their own file and only ever read others'.
# conflict rule: highest ts wins; pl_add/pl_remove ties broken in favour of
# pl_remove (delete-wins).

_DBX_ACTION_LOCAL_MARKER = '_dbx_actions_last_pushed_id'

def _dbx_push_actions(dbx):
    """append any local sync_actions rows not yet uploaded to this device's
    own action file. returns True if anything was pushed."""
    device_id = _dbx_get_device_id()
    last_pushed = CFG.get(_DBX_ACTION_LOCAL_MARKER, '')
    with db() as c:
        marker_rowid = None
        if last_pushed:
            mrow = c.execute("SELECT rowid FROM sync_actions WHERE id=?", (last_pushed,)).fetchone()
            marker_rowid = mrow[0] if mrow else None
        if marker_rowid is not None:
            cur = c.execute(
                "SELECT id,device_id,ts,action,target,target2,payload FROM sync_actions "
                "WHERE device_id=? AND rowid > ? ORDER BY rowid", (device_id, marker_rowid))
        else:
            # no marker yet, or marker row is gone - don't use rowid > NULL
            # (that's always falsy in sqlite and would silently stall pushes forever)
            cur = c.execute(
                "SELECT id,device_id,ts,action,target,target2,payload FROM sync_actions "
                "WHERE device_id=? ORDER BY rowid", (device_id,))
        new_rows = cur.fetchall()
    if not new_rows:
        return False
    remote_path = f'/meowify/actions/{device_id}.jsonl'
    import dropbox as _dbxmod
    existing = b''
    download_ok = False
    try:
        _, res = dbx.files_download(remote_path)
        existing = res.content
        download_ok = True
    except _dbxmod.exceptions.ApiError as e:
        if e.error.is_path() and e.error.get_path().is_not_found():
            download_ok = True  # file doesn't exist yet, safe to write fresh
        else:
            raise  # unexpected API error, abort rather than risk data loss
    if not download_ok:
        raise RuntimeError('could not download existing action log; aborting push to avoid data loss')
    lines = [json.dumps(dict(zip(
        ('id','device_id','ts','action','target','target2','payload'), r
    ))).encode() for r in new_rows]
    data = existing + (b'\n' if existing and not existing.endswith(b'\n') else b'') \
           + b'\n'.join(lines) + b'\n'
    dbx.files_upload(data, remote_path, mode=_dbxmod.files.WriteMode.overwrite, mute=True)
    with _cfg_lock:
        CFG[_DBX_ACTION_LOCAL_MARKER] = new_rows[-1][0]
        save_cfg(CFG)
    return True

def _dbx_pull_actions(dbx, own_device_id):
    """download every peer device's action file, apply rows not yet seen
    locally. returns list of newly-applied action dicts."""
    try:
        peer_ids = [d for d in _dbx_list_device_ids(dbx) if d != own_device_id]
    except Exception:
        return []
    with db() as c:
        seen_ids = {r[0] for r in c.execute("SELECT id FROM sync_actions").fetchall()}
    new_actions = []
    for peer_id in peer_ids:
        try:
            _, res = dbx.files_download(f'/meowify/actions/{peer_id}.jsonl')
        except Exception:
            continue
        for line in res.content.decode().splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                act = json.loads(line)
            except Exception:
                continue
            if act.get('id') in seen_ids:
                continue
            new_actions.append(act)
    if not new_actions:
        return []
    new_actions.sort(key=lambda a: a.get('ts', 0))
    with db() as c:
        for act in new_actions:
            c.execute(
                "INSERT OR IGNORE INTO sync_actions "
                "(id,device_id,ts,action,target,target2,payload) VALUES (?,?,?,?,?,?,?)",
                (act['id'], act['device_id'], act['ts'], act['action'],
                 act['target'], act.get('target2'), act.get('payload')))
        _dbx_apply_actions(c, new_actions)
    return new_actions

def _dbx_apply_song_unlink_album(c, song_sync_id, action_ts=0):
    row = c.execute("SELECT id, album_id, modified_at FROM songs WHERE sync_id=?", (song_sync_id,)).fetchone()
    if not row:
        return
    sid, album_id, local_modat = row[0], row[1], row[2]
    if local_modat and action_ts and local_modat > action_ts:
        return  # local is newer, don't clobber
    c.execute("UPDATE songs SET album_id=NULL, album=NULL, modified_at=? WHERE id=?", (int(_time.time()), sid))
    c.execute("DELETE FROM album_tracks WHERE song_id=?", (sid,))
    # if album is now completely empty, tombstone it
    if album_id:
        remaining = c.execute("SELECT COUNT(*) FROM songs WHERE album_id=?", (album_id,)).fetchone()[0]
        owned = c.execute("SELECT COUNT(*) FROM album_tracks WHERE album_id=? AND song_id IS NOT NULL", (album_id,)).fetchone()[0]
        if remaining == 0 and owned == 0:
            c.execute("DELETE FROM album_tracks WHERE album_id=?", (album_id,))
            c.execute("DELETE FROM albums WHERE id=?", (album_id,))
            # no _record_sync_action here — apply path never emits back to sync

def _dbx_apply_song_set_album(c, song_sync_id, album_id, action_ts=0):
    row = c.execute("SELECT id, modified_at FROM songs WHERE sync_id=?", (song_sync_id,)).fetchone()
    alb = c.execute("SELECT id, title FROM albums WHERE id=?", (album_id,)).fetchone()
    if not row or not alb:
        return
    sid, local_modat = row[0], row[1]
    if local_modat and action_ts and local_modat > action_ts:
        return  # local is newer, don't clobber
    c.execute("UPDATE songs SET album_id=?, album=?, modified_at=? WHERE id=?",
              (album_id, alb[1], int(_time.time()), sid))
    ex = c.execute("SELECT id FROM album_tracks WHERE album_id=? AND song_id=?", (album_id, sid)).fetchone()
    if not ex:
        c.execute("INSERT INTO album_tracks (id, album_id, song_id) VALUES (?,?,?)",
                  (str(uuid.uuid4()), album_id, sid))

def _dbx_apply_actions(c, actions):
    for act in actions:
        kind, target, target2 = act['action'], act['target'], act.get('target2')
        ts = act['ts']
        try:
            if kind == 'song_delete':
                _dbx_apply_song_delete(c, target)
            elif kind == 'song_unlink_album':
                _dbx_apply_song_unlink_album(c, target, action_ts=ts)
            elif kind == 'song_set_album':
                _dbx_apply_song_set_album(c, target, target2, action_ts=ts)
            elif kind == 'album_delete':
                c.execute("DELETE FROM album_tracks WHERE album_id=?", (target,))
                c.execute("DELETE FROM albums WHERE id=?", (target,))
            elif kind == 'artist_delete':
                c.execute("DELETE FROM song_artists WHERE artist_id=?", (target,))
                c.execute("DELETE FROM artists WHERE id=?", (target,))
            elif kind == 'pl_delete':
                c.execute("DELETE FROM playlists WHERE sync_id=?", (target,))
            elif kind in ('pl_add', 'pl_remove'):
                _dbx_apply_membership(c, target, target2)
            elif kind == 'pref_reset':
                _dbx_apply_pref_reset(target, ts)
            elif kind == 'mv_delete':
                c.execute("UPDATE songs SET mv_video_id=NULL, mv_offset=NULL WHERE sync_id=?", (target,))
            elif kind == 'lyrics_delete':
                c.execute("DELETE FROM lyrics WHERE song_id=(SELECT id FROM songs WHERE sync_id=?)", (target,))
        except Exception as e:
            _log_dbx.warning(f'[dbx actions] apply {kind} failed: {e}')

def _dbx_apply_song_delete(c, song_sync_id):
    row = c.execute(
        "SELECT id,file_path,cover_path,album_id FROM songs WHERE sync_id=?",
        (song_sync_id,)).fetchone()
    if not row:
        return
    sid, file_path, cover_path, album_id = row[0], row[1], row[2], row[3]
    c.execute("DELETE FROM songs WHERE id=?", (sid,))
    c.execute("DELETE FROM playlist_songs WHERE song_id=?", (sid,))
    c.execute("UPDATE album_tracks SET song_id=NULL WHERE song_id=?", (sid,))
    if album_id:
        remaining = c.execute("SELECT COUNT(*) FROM songs WHERE album_id=?", (album_id,)).fetchone()[0]
        if remaining == 0:
            owned = c.execute(
                "SELECT COUNT(*) FROM album_tracks WHERE album_id=? AND song_id IS NOT NULL",
                (album_id,)).fetchone()[0]
            if owned == 0:
                c.execute("DELETE FROM album_tracks WHERE album_id=?", (album_id,))
                c.execute("DELETE FROM albums WHERE id=?", (album_id,))
                _record_sync_action('album_delete', album_id, conn=c)
    if file_path:
        try: os.remove(file_path)
        except Exception: pass
    if cover_path:
        try: _safe_remove_cover(cover_path, exclude_song_id=sid)
        except Exception: pass

def _dbx_apply_membership(c, playlist_sync_id, song_sync_id):
    """resolve the winning pl_add/pl_remove for this pair from full history,
    then make local state match. highest ts wins; pl_remove wins ties."""
    rows = c.execute(
        "SELECT action, ts FROM sync_actions "
        "WHERE action IN ('pl_add','pl_remove') AND target=? AND target2=?",
        (playlist_sync_id, song_sync_id)).fetchall()
    if not rows:
        return
    best_ts = max(r[1] for r in rows)
    tied = [r[0] for r in rows if r[1] == best_ts]
    winner = 'pl_remove' if 'pl_remove' in tied else tied[0]
    pl_row   = c.execute("SELECT id FROM playlists WHERE sync_id=?", (playlist_sync_id,)).fetchone()
    song_row = c.execute("SELECT id FROM songs WHERE sync_id=?", (song_sync_id,)).fetchone()
    if not pl_row or not song_row:
        return
    pid, sid = pl_row[0], song_row[0]
    if winner == 'pl_remove':
        c.execute("DELETE FROM playlist_songs WHERE playlist_id=? AND song_id=?", (pid, sid))
    else:
        if not c.execute("SELECT 1 FROM playlist_songs WHERE playlist_id=? AND song_id=?", (pid, sid)).fetchone():
            pos = c.execute(
                "SELECT COALESCE(MAX(position),0)+1 FROM playlist_songs WHERE playlist_id=?",
                (pid,)).fetchone()[0]
            c.execute("INSERT INTO playlist_songs VALUES (?,?,?)", (pid, sid, pos))

# KNOWN LIMITATION: ts is a raw wall-clock timestamp (int(time.time())) taken on
# whichever peer device recorded the action - there is no NTP verification or
# logical/vector clock behind this comparison. If two devices' clocks are skewed
# by more than _PREF_RESET_SKEW_TOLERANCE_SECS, a genuine reset from a slow-clocked
# device can still be dropped, or a stale reset from a fast-clocked device can still
# override a fresher local edit. A full fix needs NTP-verified time or per-device
# logical clocks; this tolerance window is a cheap partial mitigation, not a fix.
_PREF_RESET_SKEW_TOLERANCE_SECS = 120

def _dbx_apply_pref_reset(key, ts):
    if key not in _DEFS:
        return
    with _cfg_lock:
        # only apply if this reset action is more recent than any genuine local
        # edit. _prefs_local_modified is bumped only by api_set_cfg (real user
        # actions). Must NOT fall back to _prefs_modified, since that field is
        # also bumped by _dbx_pull_prefs (remote pulls) and would incorrectly
        # mask a peer's legitimate reset behind an unrelated pull timestamp.
        local_modified = CFG.get('_prefs_local_modified', 0)
        if ts < local_modified - _PREF_RESET_SKEW_TOLERANCE_SECS:
            return
        CFG[key] = _DEFS[key]
        save_cfg(CFG)

_dbx_status_msg = ''

def _dbx_bg_poll():
    while not _dbx_stop.wait(300):  # every 5 min
        if not CFG.get('dropbox_sync_enabled') or not CFG.get('dropbox_refresh_token'):
            continue
        if not _dbx_lock.acquire(blocking=False):
            continue  # manual sync in progress, skip this cycle
        try:
            global _dbx_status_msg
            _dbx_status_msg = 'auto-syncing...'
            sync_lib = CFG.get('sync_library', True)
            dbx_sync_now(push_db=sync_lib,
                         pull_db=sync_lib,
                         push_songs=False,  # relay mode: pushes follow peer manifests (_dbx_needs_push), push_songs no longer bypasses
                         pull_songs=sync_lib,
                         sync_settings=CFG.get('sync_settings', True),
                         status_cb=lambda m: _set_dbx_status(m))
        except Exception as _se:
            _log_dbx.error(f'[dbx sync] unhandled error: {_se}', exc_info=True)
        finally:
            _dbx_status_msg = ''
            _dbx_lock.release()

def _dbx_start_poll():
    global _dbx_sync_thread
    if _dbx_sync_thread and _dbx_sync_thread.is_alive():
        return
    _dbx_stop.clear()
    _dbx_sync_thread = threading.Thread(target=_dbx_bg_poll, daemon=True, name='dbx-poll')
    _dbx_sync_thread.start()

_dbx_start_poll()

def _dbx_pkce_start(android=False):
    """generate PKCE verifier + challenge, return auth url.
    desktop: spins up temp localhost:19988 server to catch redirect.
    android: uses flask's own /dropbox-callback route as redirect uri."""
    import base64, hashlib as _hl, secrets as _sec, http.server, urllib.parse
    verifier = _sec.token_urlsafe(64)
    digest = _hl.sha256(verifier.encode()).digest()
    challenge = base64.urlsafe_b64encode(digest).rstrip(b'=').decode()

    if android:
        redirect_uri = 'meowify://dropbox-callback'
        _dbx_pkce_state.clear()
        _dbx_pkce_state.update({'verifier': verifier, 'redirect_uri': redirect_uri, 'done': threading.Event()})
        auth_url = (
            'https://www.dropbox.com/oauth2/authorize'
            f'?client_id={_DBX_APP_KEY}'
            f'&redirect_uri={urllib.parse.quote(redirect_uri)}'
            '&response_type=code'
            '&token_access_type=offline'
            '&code_challenge_method=S256'
            f'&code_challenge={challenge}'
        )
        return auth_url

    port = 19988  # fixed port - must be registered in dropbox app console as http://localhost:19988
    redirect_uri = f'http://localhost:{port}'

    auth_url = (
        'https://www.dropbox.com/oauth2/authorize'
        f'?client_id={_DBX_APP_KEY}'
        f'&redirect_uri={urllib.parse.quote(redirect_uri)}'
        '&response_type=code'
        '&token_access_type=offline'
        '&code_challenge_method=S256'
        f'&code_challenge={challenge}'
    )

    if _dbx_pkce_state.get('server'):
        # an earlier connect click may still be blocked in handle_request(): poke it so its
        # thread closes the socket and frees the port before we bind again
        try:
            socket.create_connection(('127.0.0.1', port), timeout=1).close()
            time.sleep(0.1)
        except Exception: pass
    _dbx_pkce_state.clear()
    _dbx_pkce_state.update({'verifier': verifier, 'redirect_uri': redirect_uri, 'port': port, 'done': threading.Event()})

    # temp HTTP server - catches the single redirect then shuts down
    class _Handler(http.server.BaseHTTPRequestHandler):
        def log_message(self, *a): pass
        def do_GET(self):
            parsed = urllib.parse.urlparse(self.path)
            params = urllib.parse.parse_qs(parsed.query)
            code = (params.get('code') or [''])[0]
            _dbx_pkce_state['code'] = code
            body = b'<html><body><h2>meowify: dropbox connected!</h2><p>you can close this tab.</p></body></html>' if code else b'<html><body><h2>error - no code received</h2></body></html>'
            self.send_response(200)
            self.send_header('Content-Type', 'text/html')
            self.end_headers()
            self.wfile.write(body)
            _dbx_pkce_state['done'].set()

    srv = http.server.HTTPServer(('127.0.0.1', port), _Handler)
    _dbx_pkce_state['server'] = srv

    def _serve():
        srv.handle_request()  # handle exactly one request then stop
        srv.server_close()
    threading.Thread(target=_serve, daemon=True).start()

    return auth_url

def _dbx_pkce_finish(skip_wait=False):
    """wait for callback (up to 120s), exchange code for refresh token, save"""
    import urllib.request, urllib.parse, json as _json
    if not skip_wait:
        done = _dbx_pkce_state.get('done')
        if not done or not done.wait(timeout=120):
            return False, 'timed out waiting for dropbox callback'
    code = _dbx_pkce_state.get('code', '')
    if not code:
        return False, 'no code received'
    verifier     = _dbx_pkce_state.get('verifier', '')
    redirect_uri = _dbx_pkce_state.get('redirect_uri', 'meowify://dropbox-callback')
    if not verifier:
        return False, 'auth session expired - please try connecting again'
    try:
        # manual token exchange - avoids SDK flow mismatch issues
        body = urllib.parse.urlencode({
            'code':          code,
            'grant_type':    'authorization_code',
            'client_id':     _DBX_APP_KEY,
            'redirect_uri':  redirect_uri,
            'code_verifier': verifier,
        }).encode()
        req = urllib.request.Request(
            'https://api.dropboxapi.com/oauth2/token',
            data=body,
            headers={'Content-Type': 'application/x-www-form-urlencoded'},
        )
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = _json.loads(resp.read())
        _log_dbx.info(f'[dbx token exchange] keys={list(data.keys())} has_refresh={bool(data.get("refresh_token"))}')
        refresh_token = data.get('refresh_token', '')
        if not refresh_token:
            _log_dbx.warning(f'[dbx token exchange] no refresh_token in response keys={list(data.keys())}')
            return False, 'no refresh token in response'
        with _cfg_lock:
            CFG['dropbox_refresh_token'] = refresh_token
            CFG['dropbox_sync_enabled']  = True
            save_cfg(CFG)
        _dbx_start_poll()
        return True, None
    except Exception as e:
        return False, str(e)

@app.route('/api/dropbox/connect', methods=['POST'])
def api_dbx_connect():
    """start PKCE flow (desktop) or return manual-code auth url (android)"""
    try:
        if IS_ANDROID:
            # android: no localhost server possible - return url + manual code entry
            url = _dbx_pkce_start(android=True)
            return jsonify({'ok': True, 'url': url, 'manual': True})
        url = _dbx_pkce_start()
        def _finish_bg():
            ok, err = _dbx_pkce_finish()
            global _dbx_status_msg
            _dbx_status_msg = '' if ok else ('connect error: ' + (err or ''))
            _log_dbx.warning(f'[dbx connect] ok={ok} err={err}')
        threading.Thread(target=_finish_bg, daemon=True).start()
        return jsonify({'ok': True, 'url': url, 'manual': False})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/dropbox/submit-code', methods=['POST'])
def api_dbx_submit_code():
    """android: user pastes the code shown after dropbox auth"""
    code = (request.json or {}).get('code', '').strip()
    if not code:
        return jsonify({'error': 'no code'}), 400
    _dbx_pkce_state['code'] = code
    done = _dbx_pkce_state.get('done')
    if done:
        done.set()
    def _finish_bg():
        ok, err = _dbx_pkce_finish(skip_wait=True)
        global _dbx_status_msg
        _dbx_status_msg = '' if ok else ('connect error: ' + (err or ''))
        _log_dbx.warning(f'[dbx connect android] ok={ok} err={err}')
    threading.Thread(target=_finish_bg, daemon=True).start()
    return jsonify({'ok': True})

@app.route('/dropbox-callback')
def dropbox_callback():
    """android webview lands here after dropbox oauth - extract code, trigger exchange,
    then redirect back to meowify so the webview returns to the app"""
    code = request.args.get('code', '').strip()
    error = request.args.get('error', '')
    if error or not code:
        import html as _html
        return f'<html><body><h2>dropbox auth failed: {_html.escape(error) or "no code"}</h2></body></html>', 400
    _dbx_pkce_state['code'] = code
    done = _dbx_pkce_state.get('done')
    if done:
        done.set()
    def _finish_bg():
        ok, err = _dbx_pkce_finish(skip_wait=True)
        global _dbx_status_msg
        _dbx_status_msg = '' if ok else ('connect error: ' + (err or ''))
        _log_dbx.warning(f'[dbx callback] ok={ok} err={err}')
    threading.Thread(target=_finish_bg, daemon=True).start()
    # redirect webview back to meowify - settings will show connected state
    flask_port = _cached_port()
    return f'''<html><head><meta http-equiv="refresh" content="1;url=http://localhost:{flask_port}/#settings"></head>
<body style="font-family:sans-serif;padding:32px;background:#1a1a1a;color:#fff">
<h2 style="color:#4caf50">&#x2713; dropbox connected!</h2>
<p style="color:#aaa">returning to meowify...</p>
</body></html>'''

@app.route('/api/dropbox/connect-status')
def api_dbx_connect_status():
    """frontend polls this after opening the browser to know when auth completes"""
    connected = bool(CFG.get('dropbox_refresh_token'))
    done = _dbx_pkce_state.get('done')
    waiting = done is not None and not done.is_set()
    return jsonify({'connected': connected, 'waiting': waiting})

@app.route('/api/dropbox/refresh-peers')
def api_dbx_refresh_peers():
    """fetch fresh peer manifests from dropbox without running a full sync."""
    try:
        dbx = _dbx()
        if not dbx:
            return jsonify({'ok': False, 'error': 'not connected'})
        own_id = _dbx_get_device_id()
        peers  = _dbx_read_peer_manifests(dbx, own_id)
        return jsonify({'ok': True, 'peers': [
            {'device_id':   m.get('device_id', ''),
             'device_name': m.get('device_name', '?'),
             'last_seen':   m.get('last_seen', 0),
             'song_count':  len(m.get('song_sync_ids', []))}
            for m in peers
        ]})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)})

@app.route('/api/dropbox/remove-device', methods=['POST'])
def api_dbx_remove_device():
    """delete a peer device manifest from dropbox."""
    try:
        data      = request.get_json(force=True)
        device_id = (data or {}).get('device_id', '').strip()
        if not device_id:
            return jsonify({'ok': False, 'error': 'missing device_id'})
        own_id = _dbx_get_device_id()
        if device_id == own_id:
            return jsonify({'ok': False, 'error': 'cannot remove own device — use disconnect'})
        dbx = _dbx()
        if not dbx:
            return jsonify({'ok': False, 'error': 'not connected'})
        dbx.files_delete_v2(f'/meowify/devices/{device_id}.json')
        # evict from cache so status route reflects removal immediately
        global _dbx_last_peer_manifests
        _dbx_last_peer_manifests = [m for m in _dbx_last_peer_manifests
                                     if m.get('device_id') != device_id]
        return jsonify({'ok': True})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)})

@app.route('/api/dropbox/disconnect', methods=['POST'])
def api_dbx_disconnect():
    try:
        dbx = _dbx()
        device_id = CFG.get('device_id', '')
        if dbx and device_id:
            try:
                dbx.files_delete_v2(f'/meowify/devices/{device_id}.json')
            except Exception:
                pass
    except Exception:
        pass
    with _cfg_lock:
        CFG['dropbox_refresh_token'] = ''
        CFG['dropbox_sync_enabled']  = False
        CFG.pop('dropbox_app_key', None)
        CFG.pop('dropbox_app_secret', None)
        save_cfg(CFG)
    _dbx_pkce_state.clear()
    return jsonify({'ok': True})

_dbx_sync_result  = None   # last completed sync result dict
_dbx_sync_running = False  # True while a manual sync is in flight
_dbx_sync_lock    = threading.Lock()  # guards _dbx_sync_running flag itself
_dbx_db_ready     = False  # flips True after db merge+actions, before file downloads

# per-category live progress for the settings-tab checklist UI. each category is
# {done, total, items: [{name, done}]}. reset at the start of every sync, updated
# as each category's loop runs, read (read-only) by /api/dropbox/status.
_dbx_progress_lock = threading.Lock()
_dbx_progress = {}

def _dbx_prog_reset():
    with _dbx_progress_lock:
        _dbx_progress.clear()

def _dbx_prog_init(cat, names):
    """seed a category with its full pending item list before iterating."""
    with _dbx_progress_lock:
        _dbx_progress[cat] = {'done': 0, 'total': len(names),
                               'items': [{'name': n, 'done': False} for n in names]}

def _dbx_prog_tick(cat, name):
    """mark one item in a category done."""
    with _dbx_progress_lock:
        entry = _dbx_progress.get(cat)
        if not entry:
            return
        entry['done'] = min(entry['done'] + 1, entry['total'])
        for it in entry['items']:
            if it['name'] == name and not it['done']:
                it['done'] = True
                break

@app.route('/api/dropbox/sync', methods=['POST'])
def api_dbx_sync():
    global _dbx_sync_running
    with _dbx_sync_lock:
        if _dbx_sync_running:
            return jsonify({'ok': False, 'error': 'sync already in progress'})
        _dbx_sync_running = True  # set atomically under lock
    data = request.json or {}
    push_songs    = data.get('push_songs', False)
    sync_settings = CFG.get('sync_settings', True)
    sync_library  = CFG.get('sync_library', True)

    def _run():
        global _dbx_sync_running, _dbx_sync_result, _dbx_status_msg
        if not _dbx_lock.acquire(blocking=False):
            with _dbx_sync_lock:
                _dbx_sync_running = False
            return  # bg poll running, bail
        try:
            r = dbx_sync_now(push_db=sync_library, pull_db=sync_library,
                             push_songs=push_songs, pull_songs=sync_library,
                             sync_settings=sync_settings,
                             status_cb=lambda m: _set_dbx_status(m))
            _dbx_sync_result = r
        except Exception as e:
            _dbx_sync_result = {'error': str(e)}
        finally:
            with _dbx_sync_lock:
                _dbx_sync_running = False
            _dbx_status_msg   = ''
            _dbx_lock.release()

    global _dbx_db_ready
    _dbx_db_ready = False  # reset before each sync
    threading.Thread(target=_run, daemon=True, name='dbx-manual-sync').start()
    return jsonify({'ok': True, 'async': True})

def _set_dbx_status(m):
    global _dbx_status_msg
    _dbx_status_msg = m

@app.route('/api/dropbox/status')
def api_dbx_status():
    connected = bool(CFG.get('dropbox_refresh_token'))
    last = CFG.get('dropbox_last_sync', 0)
    peers = [{'device_id': m.get('device_id', ''), 'device_name': m.get('device_name', '?'),
               'last_seen': m.get('last_seen', 0), 'song_count': len(m.get('song_sync_ids', []))}
             for m in _dbx_last_peer_manifests]
    with _dbx_progress_lock:
        progress = {k: {'done': v['done'], 'total': v['total'], 'items': v['items']}
                    for k, v in _dbx_progress.items()}
    return jsonify({
        'connected':   connected,
        'enabled':     CFG.get('dropbox_sync_enabled', False),
        'last_sync':   last,
        'status':      _dbx_status_msg,
        'syncing':     _dbx_sync_running,
        'db_ready':    _dbx_db_ready,
        'last_result': _dbx_sync_result,
        'this_device': {'device_id': CFG.get('device_id', ''), 'device_name': _dbx_get_device_name()},
        'peers':       peers,
        'progress':    progress,
    })

@app.route('/api/deps', methods=['GET'])
def api_deps():
    import shutil
    def _has(mod):
        import importlib.util
        return importlib.util.find_spec(mod) is not None
    # on android yt-dlp runs in-process via yt_dlp package; on desktop it's a binary
    if IS_ANDROID:
        try:
            import yt_dlp as _yt
            ytdlp_installed = bool(getattr(_yt, 'version', None))
        except ImportError:
            ytdlp_installed = False
    else:
        ytdlp_installed = shutil.which('yt-dlp') is not None
    return jsonify({
        'numpy':              _has('numpy'),
        'miniaudio':          _has('miniaudio'),
        'scipy':              _has('scipy'),
        'ytmusicapi':         _has('ytmusicapi'),
        'torch':              _has('torch'),
        'ctc_forced_aligner': _has('ctc_forced_aligner'),
        'yt_dlp':             ytdlp_installed,
        'dropbox':            _has('dropbox'),
    })

@app.route('/api/settings', methods=['GET'])
def api_get_cfg():
    with _cfg_lock:
        c = dict(CFG)
    c.pop('dropbox_refresh_token', None)
    c['_platform'] = sys.platform
    return jsonify(c)

@app.route('/api/restart', methods=['POST'])
def api_restart():
    """restart the meowify process (used after settings that require restart)"""
    def _do_restart():
        time.sleep(0.4)
        try:
            os.execv(sys.executable, [sys.executable] + sys.argv)
        except Exception:
            os._exit(0)
    threading.Thread(target=_do_restart, daemon=True).start()
    return jsonify({'ok': True})

# ── music video backend ────────────────────────────────────────────────────────
def _mv_ytdlp_stream_url(video_id):
    """Get direct video stream URLs for a YouTube video_id via yt-dlp.
    Returns (video_url, expires_at) or raises on failure."""
    cmd = [
        'yt-dlp', '--no-warnings', '-J',
        '--format', 'bestvideo[height<=1080][ext=mp4]+bestaudio[ext=m4a]/bestvideo[height<=1080]+bestaudio/best',
        '--', f'https://www.youtube.com/watch?v={video_id}'
    ]
    result = _subrun(cmd, capture_output=True, text=True, timeout=30)
    if result.returncode != 0:
        raise RuntimeError(f'yt-dlp failed: {result.stderr[:200]}')
    info = json.loads(result.stdout)
    # find video-only and audio-only streams
    formats = info.get('formats', [])
    video_url = None
    # prefer video-only stream (no audio) for video element (we sync our own audio)
    for f in reversed(formats):
        if f.get('vcodec', 'none') != 'none' and f.get('acodec', 'none') == 'none':
            if f.get('height', 0) <= 1080:
                video_url = f.get('url')
                break
    # fallback: combined stream if no video-only found
    if not video_url:
        for f in reversed(formats):
            if f.get('vcodec', 'none') != 'none':
                if f.get('height', 0) <= 1080:
                    video_url = f.get('url')
                    break
    if not video_url:
        raise RuntimeError('no suitable video stream found')
    # estimate expiry from url fragment (YouTube stream urls expire in ~6h)
    import re as _re
    exp_m = _re.search(r'[?&]expire=(\d+)', video_url)
    expires_at = int(exp_m.group(1)) if exp_m else int(time.time()) + 3600 * 5
    exp_in = int(expires_at - time.time()) // 60
    _log_mv.debug(f'[mv stream] got url for {video_id} expires_in={exp_in}m')
    return video_url, expires_at

def _mv_cross_correlate_offset(song_path, mv_audio_path):
    """Cross-correlate song audio vs mv audio to find time offset in seconds.
    Returns offset in seconds: positive = MV audio leads song (MV starts before song);
    negative = MV audio lags song (MV has a long intro after song audio begins).
    Returns None if no confident match found."""
    try:
        np = _import_numpy()
        ma = _import_miniaudio()

        def _load_mono(path, max_secs=120):
            decoded = ma.decode_file(str(path), ma.SampleFormat.FLOAT32, nchannels=1, sample_rate=22050)
            samples = np.frombuffer(decoded.samples, dtype=np.float32)
            max_frames = int(max_secs * 22050)
            return samples[:max_frames], 22050

        song_pcm, sr = _load_mono(song_path)
        mv_pcm, _    = _load_mono(mv_audio_path)

        def _norm(x):
            m = np.max(np.abs(x))
            return x / m if m > 1e-6 else x

        song_pcm = _norm(song_pcm)
        mv_pcm   = _norm(mv_pcm)

        n = len(song_pcm) + len(mv_pcm) - 1
        fft_n = 1
        while fft_n < n:
            fft_n <<= 1

        S_fft = np.fft.rfft(song_pcm, n=fft_n)
        M_fft = np.fft.rfft(mv_pcm,   n=fft_n)
        corr  = np.fft.irfft(np.conj(S_fft) * M_fft, n=fft_n)  # circular: negative lags live at the end of fft_n

        # search both positive offsets (MV leads) and negative (MV lags)
        # corr[k]     → MV starts k/sr seconds before song  (positive offset)
        # corr[n-k]   → MV starts k/sr seconds after song   (negative offset)
        MAX_OFFSET_SECS = 90
        max_lag = int(MAX_OFFSET_SECS * sr)

        pos_search = corr[:max_lag + 1]
        neg_search = corr[fft_n - max_lag:fft_n]

        pos_peak_idx = int(np.argmax(np.abs(pos_search)))
        pos_peak_val = float(np.abs(pos_search[pos_peak_idx]))

        neg_peak_idx = int(np.argmax(np.abs(neg_search)))
        neg_peak_val = float(np.abs(neg_search[neg_peak_idx]))

        # pick whichever side has the stronger peak
        if pos_peak_val >= neg_peak_val:
            peak_val   = pos_peak_val
            offset_secs = pos_peak_idx / sr
        else:
            peak_val    = neg_peak_val
            # neg_peak_idx is an index *within* neg_search (which starts at
            # corr[n-max_lag]), not a distance from the end of corr — convert
            offset_secs = -(len(neg_search) - neg_peak_idx) / sr

        # dynamic confidence threshold: longer signals give noisier xcorr baseline
        # so we scale the threshold slightly with signal length. Floor raised
        # from 3.0-5.0 to 12.0-16.0: empirically, cross-correlating two
        # *unrelated* audio signals still produces a peak/noise-floor ratio of
        # ~3.5-4.4 purely by chance (tested over 60 trials across quiet and
        # normal amplitudes), which sat right at the old threshold - meaning
        # low-signal/ambient songs could randomly "confidently" match the
        # wrong video with no user-facing indication beyond a silently wrong
        # sync. A genuine match scores in the hundreds regardless of signal
        # loudness, so there's a huge safety margin between real matches and
        # the noise ceiling - raising the floor only rejects noise, not
        # legitimate low-signal matches.
        threshold_val = float(np.percentile(np.abs(corr[:n]), 95))
        confidence = peak_val / (threshold_val + 1e-9)
        min_confidence = max(12.0, min(16.0, 12.0 + (min(len(song_pcm), len(mv_pcm)) / sr) / 60.0))

        _log_mv.debug(f'[mv xcorr] offset={offset_secs:.2f}s confidence={confidence:.2f} (need {min_confidence:.1f})')

        if confidence < min_confidence:
            return None

        return round(offset_secs, 3)

    except Exception as e:
        _log_mv.warning(f'[mv xcorr] error: {e}')
        return None

def _mv_persist(song_id, video_id, offset):
    """Persist MV video_id + offset to the songs table for cache survival across restarts."""
    try:
        with db() as c:
            c.execute("UPDATE songs SET mv_video_id=?, mv_offset=? WHERE id=?",
                      (video_id, offset, song_id))
        _log_mv.info(f'[mv] persisted video={video_id} offset={offset:.2f}s song={song_id}')
    except Exception as e:
        # column may not exist yet if schema hasn't been migrated - silently ignore
        _log_mv.warning(f'[mv] persist err (expected on first run): {e}')

def _mv_find_and_cache(song_id, artist, title, my_gen, hint_video_id=None):
    """Background worker: search YTMusic for MV, download audio-only for xcorr,
    compute offset, cache result.  Updates _mv_cache[song_id] in-place.
    my_gen is checked before each expensive step; if _mv_find_gen has advanced
    (song changed), we abort early to avoid wasting resources.
    hint_video_id: if provided (e.g. from genius metadata), try this video first
    before falling back to a fresh ytmusic search."""
    import tempfile, os as _os

    def _cancelled():
        with _mv_find_gen_lock:
            gone = _mv_find_gen != my_gen
        if gone:
            # drop our own in-progress marker so the next poll can retry instead of seeing 'searching' forever
            with _mv_cache_lock:
                e = _mv_cache.get(song_id)
                if e and e.get('status') in ('searching', 'downloading', 'correlating') and e.get('_gen', my_gen) == my_gen:
                    _mv_cache.pop(song_id, None)
        return gone

    def _set(status, **kw):
        # only write if we're still the active job for this song
        if _cancelled(): return
        with _mv_cache_lock:
            _mv_cache[song_id] = {'status': status, '_gen': my_gen, **kw}

    _set('searching')
    try:
        if _cancelled(): return

        # build candidate list: hint first (skip search if it xcorrs cleanly),
        # then fall back to a fresh ytmusic search
        hint_candidates = [{'videoId': hint_video_id, 'title': '(hint)'}] if hint_video_id else []
        yt = _import_ytmusic()
        query = f'{artist} {title}'.strip()
        results = yt.search(query, filter='videos', limit=8, ignore_spelling=True)

        search_candidates = [r for r in results if r.get('videoId')
                             and r.get('videoId') != hint_video_id]
        candidates = hint_candidates + search_candidates
        if not candidates:
            _set('not_found')
            return

        def _is_likely_mv(r):
            t = (r.get('title') or '').lower()
            a = (r.get('artists') or [{}])[0].get('name', '').lower() if r.get('artists') else ''
            # hard exclusions
            for bad in ('lyric video', 'lyrics video', 'lyrics', 'karaoke',
                        'cover by', '(cover)', 'fan made', 'fan-made', 'reaction'):
                if bad in t: return False
            # soft: prefer entries whose channel/artist matches our artist
            return True

        def _mv_score(r):
            t = (r.get('title') or '').lower()
            score = 0
            # "official (music) video" and common non-English equivalents - additive
            # only, so this can't regress any existing English match, just adds
            # coverage for correctly-labeled non-English uploads that previously
            # got no scoring boost at all
            for good in ('official music video', 'official mv', 'official video', 'music video',
                         'oficjalny teledysk', 'oficjalne wideo',           # polish
                         'video oficial', 'vídeo oficial',                  # spanish/portuguese
                         'clip officiel', 'vidéo officielle',               # french
                         'offizielles video', 'offizielles musikvideo',     # german
                         'video ufficiale',                                 # italian
                         'официальное видео', 'официальный клип',           # russian
                         '公式mv', '公式video', 'ミュージックビデオ',            # japanese
                         'official m/v', '공식 뮤직비디오', '뮤직비디오'):       # korean
                if good in t: score += 2
            for ok in ('official', 'mv', 'video', 'teledysk', 'oficjalny', 'oficial'):
                if ok in t: score += 0.5
            return score

        # hint candidate bypasses scoring/filtering — always goes first as-is
        hint_cands  = [c for c in candidates if c.get('videoId') == hint_video_id]
        search_cands = [c for c in candidates if c.get('videoId') != hint_video_id]
        good = [r for r in search_cands if _is_likely_mv(r)]
        ordered = hint_cands + sorted(good or search_cands, key=_mv_score, reverse=True)

        if _cancelled(): return

        with db() as c:
            row = c.execute("SELECT file_path FROM songs WHERE id=?", (song_id,)).fetchone()
        if not row or not row[0] or not Path(row[0]).exists():
            _set('not_found')
            return
        song_path = row[0]

        # try up to 3 candidates until xcorr finds a confident match
        offset = None
        video_id = None
        for candidate in ordered[:3]:
            if _cancelled(): return
            vid = candidate['videoId']
            _log_mv.info(f'[mv] trying candidate: {candidate.get("title")!r} id={vid}')

            with _mv_cache_lock:
                if not _cancelled():
                    _mv_cache[song_id] = {'status': 'downloading', '_gen': my_gen, 'video_id': vid}

            tmp_dir  = tempfile.mkdtemp(prefix='meowify-mv-')
            mv_audio = Path(tmp_dir) / 'mv_audio.%(ext)s'
            try:
                cmd = [
                    'yt-dlp', '--no-warnings', '-x',
                    '--audio-format', 'wav',
                    '--audio-quality', '5',
                    # only download first 130s - xcorr uses max 120s, gives small buffer
                    '--download-sections', '*0:00-130',
                    '-o', str(mv_audio),
                    '--', f'https://www.youtube.com/watch?v={vid}'
                ]
                if _cancelled():
                    return
                res = _subrun(cmd, capture_output=True, text=True, timeout=90)
                if res.returncode != 0:
                    _log_mv.warning(f'[mv] yt-dlp failed for {vid}: {res.stderr[:200]}')
                    continue

                dl_files = list(Path(tmp_dir).glob('mv_audio.*'))
                if not dl_files:
                    continue
                mv_audio_path = str(dl_files[0])

                if _cancelled(): return
                with _mv_cache_lock:
                    if not _cancelled():
                        _mv_cache[song_id] = {'status': 'correlating', '_gen': my_gen, 'video_id': vid}

                offset = _mv_cross_correlate_offset(song_path, mv_audio_path)
            finally:
                import shutil as _sh
                _sh.rmtree(tmp_dir, ignore_errors=True)

            if offset is not None:
                video_id = vid
                break
            _log_mv.info(f'[mv] xcorr no match for {vid}, trying next candidate')

        if _cancelled(): return

        if offset is None or video_id is None:
            _log_mv.warning(f'[mv] no confident xcorr match for {song_id} after trying {len(ordered[:3])} candidates')
            _set('not_found')
            return

        _log_mv.info(f'[mv] offset={offset}s video={video_id} song={song_id}')

        try:
            video_url, expires_at = _mv_ytdlp_stream_url(video_id)
        except Exception as e:
            _log_mv.warning(f'[mv] stream url failed: {e}')
            _set('not_found')
            return

        if _cancelled(): return
        proxy_url = f'/api/mv-proxy/{video_id}'
        _set('ready', video_id=video_id, offset=offset,
             video_url=proxy_url, stream_url=video_url, expires_at=expires_at)
        _mv_persist(song_id, video_id, offset)

    except Exception as e:
        _log_mv.warning(f'[mv] _mv_find_and_cache error: {e}')
        import traceback as _tb; _tb.print_exc()
        _set('not_found')

# ── mv search/xcorr cancellation token: bumped each time a new song takes over ──
_mv_find_gen      = 0
_mv_find_gen_lock = threading.Lock()

# ── mv stream url precompute pool ─────────────────────────────────────────────
_mv_warmup_pool  = ThreadPoolExecutor(max_workers=6, thread_name_prefix='meowify-mv-warm')
atexit.register(lambda: _mv_warmup_pool.shutdown(wait=False, cancel_futures=True))
_mv_warming      = set()   # video_ids currently being warmed
_mv_warming_lock = threading.Lock()
# video_id -> {'path': str, 'done': bool, 'size': int}
_mv_file_cache   = {}
_mv_file_lock    = threading.Lock()

def _mv_prefetch_bytes(video_id, stream_url):
    """Download the full video stream to a local file so the proxy can serve
    all range requests instantly with no live upstream hits or reconnects."""
    with _mv_file_lock:
        if video_id in _mv_file_cache:
            return  # already downloading or done
        dest = str(ddir() / 'mv_cache' / f'{video_id}.mp4')
        _mv_file_cache[video_id] = {'path': dest, 'done': False, 'size': 0}
        # evict oldest if over 8 cached videos; do this before downloading
        if len(_mv_file_cache) > 8:
            oldest_id, oldest = next(iter(_mv_file_cache.items()))
            if oldest_id != video_id:
                del _mv_file_cache[oldest_id]
                try:
                    os.unlink(oldest['path'])
                except OSError:
                    pass
    try:
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        req = _urllib_request.Request(stream_url, headers={'User-Agent': 'Mozilla/5.0'})
        with _urllib_request.urlopen(req, timeout=30) as r:
            with open(dest, 'wb') as f:
                while True:
                    chunk = r.read(512 * 1024)
                    if not chunk:
                        break
                    f.write(chunk)
                    with _mv_file_lock:
                        if video_id in _mv_file_cache:
                            _mv_file_cache[video_id]['size'] = f.tell()
        size = os.path.getsize(dest)
        if size == 0:
            raise RuntimeError('empty response from CDN')
        with _mv_file_lock:
            if video_id in _mv_file_cache:
                _mv_file_cache[video_id]['done'] = True
                _mv_file_cache[video_id]['size'] = size
        _log_mv.info(f'[mv warm] file-cached {size // 1024 // 1024}MB for {video_id}')
    except Exception as e:
        _log_mv.warning(f'[mv warm] file-prefetch failed {video_id}: {e}')
        with _mv_file_lock:
            _mv_file_cache.pop(video_id, None)
        try:
            os.unlink(dest)
        except OSError:
            pass

def _mv_warm_stream_url(song_id, video_id, offset):
    """Fetch a fresh stream URL for a known video_id, populate _mv_cache,
    and pre-fetch the first 4 MB of bytes so playback starts instantly."""
    with _mv_warming_lock:
        if video_id in _mv_warming:
            return
        _mv_warming.add(video_id)
    try:
        # skip if already cached, fresh, and bytes already pre-fetched
        with _mv_cache_lock:
            existing = _mv_cache.get(song_id)
        if existing and existing.get('status') == 'ready':
            if time.time() < existing.get('expires_at', 0) - 600:
                with _mv_file_lock:
                    fc = _mv_file_cache.get(video_id)
                if fc and fc['done']:
                    return  # fully warm
                _mv_prefetch_bytes(video_id, existing['stream_url'])
                return
        _log_mv.info(f'[mv warm] fetching stream url for {video_id}')
        video_url, expires_at = _mv_ytdlp_stream_url(video_id)
        proxy_url = f'/api/mv-proxy/{video_id}'
        entry = {'status': 'ready', 'video_id': video_id, 'offset': offset,
                 'video_url': proxy_url, 'stream_url': video_url, 'expires_at': expires_at}
        with _mv_cache_lock:
            _mv_cache[song_id] = entry
        _log_mv.info(f'[mv warm] ready: song={song_id} vid={video_id}')
        # pre-fetch bytes immediately after getting URL
        _mv_prefetch_bytes(video_id, video_url)
    except Exception as e:
        _log_mv.warning(f'[mv warm] failed {video_id}: {e}')
    finally:
        with _mv_warming_lock:
            _mv_warming.discard(video_id)

def _mv_startup_prewarm():
    """On startup, pre-fetch stream URLs for songs that have mv_video_id in DB.
    Called in a daemon thread from main(); submits to warmup pool with stagger."""
    with _cfg_lock:
        if not CFG.get('music_video', False):
            return
    try:
        with db() as c:
            rows = c.execute(
                "SELECT id, mv_video_id, mv_offset FROM songs "
                "WHERE mv_video_id IS NOT NULL AND mv_offset IS NOT NULL"
            ).fetchall()
        if not rows:
            return
        _log_mv.info(f'[mv warm] startup: {len(rows)} songs with known MV - submitting background warm')
        for sid, vid, off in rows:
            _mv_warmup_pool.submit(_mv_warm_stream_url, str(sid), vid, off)
    except Exception as e:
        _log_mv.warning(f'[mv warm] startup prewarm error: {e}')

@app.route('/api/mv-warmup', methods=['POST'])
def api_mv_warmup():
    """Frontend sends a list of song_ids it wants stream URLs for ASAP.
    We look up which ones have mv_video_id and schedule immediate warming."""
    with _cfg_lock:
        if not CFG.get('music_video', False):
            return jsonify({'ok': True, 'queued': 0})
    data = request.get_json(silent=True) or {}
    song_ids = [str(s) for s in (data.get('song_ids') or [])[:20]]
    if not song_ids:
        return jsonify({'ok': True, 'queued': 0})
    queued = 0
    with db() as c:
        for sid in song_ids:
            with _mv_cache_lock:
                cached = _mv_cache.get(sid)
            if cached and cached.get('status') == 'ready':
                if time.time() < cached.get('expires_at', 0) - 600:
                    continue  # already fresh
            row = c.execute(
                "SELECT mv_video_id, mv_offset FROM songs WHERE id=? AND mv_video_id IS NOT NULL",
                (sid,)
            ).fetchone()
            if row:
                _mv_warmup_pool.submit(_mv_warm_stream_url, sid, row[0], row[1])
                queued += 1
    return jsonify({'ok': True, 'queued': queued})

@app.route('/api/songs/<sid>/music-video', methods=['GET', 'POST', 'DELETE'])
def api_mv_status(sid):
    """GET: return MV status/url. POST: set manual video_id. DELETE: clear cached MV."""
    if request.method == 'POST':
        data = request.get_json(silent=True) or {}
        video_id = (data.get('video_id') or '').strip()
        if not video_id:
            return jsonify({'ok': False, 'error': 'missing video_id'}), 400
        try:
            with db() as c:
                c.execute("UPDATE songs SET mv_video_id=?, mv_offset=NULL WHERE id=?", (video_id, sid))
        except Exception as e:
            _log_mv.warning(f'[mv] set video_id err: {e}')
            return jsonify({'ok': False, 'error': str(e)}), 500
        _log_mv.info(f'[mv] manual video_id set: song={sid} video={video_id}')
        return jsonify({'ok': True})
    if request.method == 'DELETE':
        full = request.args.get('full') == '1'
        with _mv_cache_lock:
            old = _mv_cache.pop(sid, None)
        _log_mv.info(f'[mv] clear song={sid} full={full} had_cache={old is not None}')
        if full:
            old_vid = old.get('video_id') if old else None
            if not old_vid:
                with db() as c:
                    row = c.execute("SELECT mv_video_id FROM songs WHERE id=?", (sid,)).fetchone()
                old_vid = row[0] if row else None
            try:
                with db() as c:
                    c.execute("UPDATE songs SET mv_video_id=NULL, mv_offset=NULL WHERE id=?", (sid,))
                    song_row = c.execute("SELECT sync_id FROM songs WHERE id=?", (sid,)).fetchone()
                    if song_row and song_row[0]:
                        _record_sync_action('mv_delete', song_row[0], conn=c)
            except Exception as e:
                _log_mv.warning(f'[mv] full-clear persist err: {e}')
            if old_vid:
                with _mv_file_lock:
                    fc = _mv_file_cache.pop(old_vid, None)
                if fc:
                    try:
                        os.unlink(fc['path'])
                    except OSError:
                        pass
                with _mv_warming_lock:
                    _mv_warming.discard(old_vid)
        return jsonify({'ok': True})
    # GET
    with _cfg_lock:
        enabled = CFG.get('music_video', False)
    if not enabled:
        return jsonify({'status': 'disabled'})

    # check-then-set under the lock to prevent duplicate find jobs when two
    # rapid fetches for the same sid both see cache-miss simultaneously
    with _mv_cache_lock:
        cached = _mv_cache.get(sid)
        if cached is None:
            # reserve the slot immediately so a concurrent request won't also
            # submit a find job - we'll overwrite with the real status below
            _mv_cache[sid] = {'status': 'searching'}

    if cached:
        # if warming, re-submit immediately so the current song isn't stuck
        # waiting behind the startup prewarm queue
        if cached['status'] == 'warming':
            vid = cached.get('video_id')
            off = cached.get('offset', 0)
            if vid:
                _mv_warmup_pool.submit(_mv_warm_stream_url, sid, vid, off)
        # if ready but stream URL near expiry, refresh in background
        if cached['status'] == 'ready':
            expires_at = cached.get('expires_at', 0)
            if time.time() > expires_at - 300:
                vid = cached.get('video_id')
                if vid:
                    with _mv_warming_lock:
                        already = vid in _mv_warming
                        if not already:
                            _mv_warming.add(vid)
                    if not already:
                        def _refresh(s=sid, v=vid):
                            try:
                                url, exp = _mv_ytdlp_stream_url(v)
                                with _mv_cache_lock:
                                    if _mv_cache.get(s, {}).get('video_id') == v:
                                        _mv_cache[s]['stream_url'] = url
                                        _mv_cache[s]['expires_at'] = exp
                            except Exception as _e:
                                _log_mv.warning(f'[mv] refresh failed: {_e}')
                            finally:
                                with _mv_warming_lock:
                                    _mv_warming.discard(v)
                        threading.Thread(target=_refresh, daemon=True).start()
        return jsonify(cached)

    # not cached - check DB for persisted result first
    with db() as c:
        row = c.execute("SELECT title, artist, mv_video_id, mv_offset FROM songs WHERE id=?", (sid,)).fetchone()
    if not row:
        with _mv_cache_lock:
            _mv_cache.pop(sid, None)
        return jsonify({'status': 'not_found'})

    mv_video_id = row[2] if row else None
    mv_offset   = row[3] if row else None

    if mv_video_id is not None and mv_offset is not None:
        # fully persisted result - warm stream URL in background, return 'warming' immediately
        # so the frontend poll cycle isn't blocked by a 3-5s yt-dlp call
        with _mv_cache_lock:
            _mv_cache[sid] = {'status': 'warming', 'video_id': mv_video_id, 'offset': mv_offset}
        _mv_warmup_pool.submit(_mv_warm_stream_url, sid, mv_video_id, mv_offset)
        return jsonify({'status': 'warming', 'video_id': mv_video_id, 'offset': mv_offset})

    title  = clean_title(row[0] or '', row[1] or '')
    artist = (row[1] or '').split(',')[0].strip()

    # mv_video_id exists (e.g. from genius) but no xcorr offset yet — pass as hint so
    # xcorr tries the known video first instead of searching blind from scratch
    hint = mv_video_id  # may be None, _mv_find_and_cache handles that

    # _mv_cache[sid] already set to 'searching' above under the lock
    global _mv_find_gen
    with _mv_find_gen_lock:
        _mv_find_gen += 1
        my_gen = _mv_find_gen
    _log_mv.info(f'[mv] kicking off search for song={sid} {artist!r} - {title!r} hint={hint}')
    _mv_find_pool.submit(_mv_find_and_cache, sid, artist, title, my_gen, hint_video_id=hint)
    return jsonify({'status': 'searching'})

def _mv_parse_range(range_hdr):
    """Parse 'bytes=start-end' → (start, end|None). Returns (0, None) on failure."""
    if not range_hdr:
        return 0, None
    try:
        m = re.match(r'bytes=(\d+)-(\d*)', range_hdr)
        if m:
            start = int(m.group(1))
            end   = int(m.group(2)) if m.group(2) else None
            return start, end
    except Exception:
        pass
    return 0, None

@app.route('/api/mv-proxy/<path:video_id>')
def api_mv_proxy(video_id):
    """Proxy YouTube stream through localhost. Serves from local file cache for
    instant seeks; falls back to live upstream only while file is still downloading."""
    real_url = None
    with _mv_cache_lock:
        for entry in _mv_cache.values():
            if entry.get('video_id') == video_id and entry.get('status') == 'ready':
                real_url = entry.get('stream_url')
                break
    if not real_url:
        return ('not found', 404)

    range_hdr = request.headers.get('Range')
    start, end = _mv_parse_range(range_hdr)

    # serve from local file if available and range is within downloaded portion
    with _mv_file_lock:
        fc = _mv_file_cache.get(video_id)
    if fc and os.path.exists(fc['path']) and fc['size'] > 0:
        available = fc['size']
        done = fc['done']
        req_end = end if end is not None else (available - 1)
        if start < available and (done or req_end < available):
            actual_end = min(req_end, available - 1)
            length = actual_end - start + 1
            total = str(available) if done else '*'
            def _file_generate(path, s, l):
                with open(path, 'rb') as f:
                    f.seek(s)
                    remaining = l
                    while remaining > 0:
                        chunk = f.read(min(512 * 1024, remaining))
                        if not chunk:
                            break
                        remaining -= len(chunk)
                        yield chunk
            resp_headers = {
                'Content-Type': 'video/mp4',
                'Accept-Ranges': 'bytes',
                'Content-Range': f'bytes {start}-{actual_end}/{total}',
                'Content-Length': str(length),
            }
            return Response(_file_generate(fc['path'], start, length), status=206,
                            headers=resp_headers, direct_passthrough=True)

    # live upstream fallback (file not ready or seek past downloaded portion)
    headers = {'User-Agent': 'Mozilla/5.0'}
    if range_hdr:
        headers['Range'] = range_hdr
    try:
        req = _urllib_request.Request(real_url, headers=headers)
        upstream = _urllib_request.urlopen(req, timeout=15)
        status = upstream.status
        ct = upstream.headers.get('Content-Type', 'video/mp4')
        cr = upstream.headers.get('Content-Range')
        cl = upstream.headers.get('Content-Length')
        chunk_size = 512 * 1024  # 512 KB chunks for faster streaming
        def _generate():
            try:
                while True:
                    chunk = upstream.read(chunk_size)
                    if not chunk:
                        break
                    yield chunk
            finally:
                upstream.close()
        resp_headers = {'Content-Type': ct, 'Accept-Ranges': 'bytes'}
        if cr: resp_headers['Content-Range'] = cr
        if cl: resp_headers['Content-Length'] = cl
        return Response(_generate(), status=status, headers=resp_headers, direct_passthrough=True)
    except Exception as e:
        _log_mv.warning(f'[mv-proxy] error: {e}')
        # 403 = YouTube stream URL expired; invalidate so the next status poll
        # triggers a background yt-dlp refresh via the inline _refresh thread
        if '403' in str(e) or 'Forbidden' in str(e):
            with _mv_cache_lock:
                for entry in _mv_cache.values():
                    if entry.get('video_id') == video_id and entry.get('status') == 'ready':
                        entry['expires_at'] = 0
                        break
        return ('proxy error', 502)


@app.route('/api/settings', methods=['POST'])
def api_set_cfg():
    data = request.json or {}
    with _cfg_lock:
        resets = [k for k, v in data.items()
                  if k in _DBX_SHARED_PREFS and k in _DEFS
                  and v == _DEFS[k] and CFG.get(k) != v]
        CFG.update(data)
        if any(k in _DBX_SHARED_PREFS for k in data):
            t = int(_time.time())
            CFG['_prefs_modified'] = t
            CFG['_prefs_local_modified'] = t
        save_cfg(CFG)
    for k in resets:
        _record_sync_action('pref_reset', k)
    return jsonify({'ok':True})

